import * as React from 'react';
import { Select } from '@daisforge/ui';

const statusOptions = [
  { value: 'new', label: 'Новая' },
  { value: 'in-progress', label: 'В работе' },
  { value: 'on-hold', label: 'Приостановлена' },
  { value: 'completed', label: 'Завершена' },
  { value: 'rejected', label: 'Отклонена' },
];

const statusLabels = new Map(statusOptions.map(({ value, label }) => [value, label]));

export function ApplicationStatusSelect() {
  const [selectedStatuses, setSelectedStatuses] = React.useState<string[]>([]);

  function handleStatusChange(value: string | string[]) {
    if (typeof value !== 'string') {
      setSelectedStatuses(value);
    }
  }

  const selectedLabels = selectedStatuses.map((value) => statusLabels.get(value) ?? value);

  return (
    <div>
      <Select
        items={statusOptions}
        label="Статус"
        labelPlacement="outer"
        multiselect
        value={selectedStatuses}
        onChange={handleStatusChange}
      />
      <p aria-live="polite">{selectedLabels.join(', ')}</p>
    </div>
  );
}

