import * as React from 'react';
import { Autocomplete } from '@daisforge/ui';
import { GlobalStyle } from '@daisforge/ui/styles';

const cities = [
  'Москва',
  'Санкт-Петербург',
  'Новосибирск',
  'Екатеринбург',
  'Казань',
  'Нижний Новгород',
  'Челябинск',
  'Самара',
  'Ростов-на-Дону',
  'Красноярск',
];

const citySuggestions = cities.map((city) => ({
  id: city,
  value: city,
  label: city,
}));

type CityFieldState = {
  value: string;
  selectedCity: string | null;
};

export function CityAutocomplete() {
  const [{ value, selectedCity }, setField] = React.useState<CityFieldState>({
    value: '',
    selectedCity: null,
  });
  const query = value.trim().toLocaleLowerCase('ru-RU');

  return (
    <>
      <GlobalStyle />
      <Autocomplete
        label="Город"
        placeholder="Начните вводить название города"
        autoComplete="off"
        threshold={1}
        value={value}
        suggestions={selectedCity === null && query !== '' ? citySuggestions : []}
        filter={(item) => item.label.toLocaleLowerCase('ru-RU').includes(query)}
        onChange={(event) => {
          setField({ value: event.currentTarget.value, selectedCity: null });
        }}
        onSuggestionSelect={(item) => {
          setField({ value: item.label, selectedCity: item.label });
        }}
        onClear={() => setField({ value: '', selectedCity: null })}
      />
    </>
  );
}

import * as React from 'react';
import { Autocomplete } from '@daisforge/ui';
import { GlobalStyle } from '@daisforge/ui/styles';

const citySuggestions = [
  'Москва',
  'Санкт-Петербург',
  'Новосибирск',
  'Екатеринбург',
  'Казань',
  'Нижний Новгород',
  'Челябинск',
  'Самара',
  'Уфа',
  'Красноярск',
].map((city) => ({ label: city, value: city }));

interface CityFieldState {
  input: string;
  selectedCity: string | null;
}

const emptyField: CityFieldState = { input: '', selectedCity: null };

export function CityAutocomplete() {
  const [field, setField] = React.useState<CityFieldState>(emptyField);
  const query = field.input.trim().toLocaleLowerCase('ru-RU');

  return (
    <>
      <GlobalStyle />
      <Autocomplete
        label="Город"
        placeholder="Начните вводить название города"
        autoComplete="off"
        threshold={1}
        value={field.input}
        suggestions={citySuggestions}
        filter={(item) =>
          field.selectedCity === null &&
          query.length > 0 &&
          item.label.toLocaleLowerCase('ru-RU').includes(query)
        }
        onChange={(event) => {
          const input = event.currentTarget.value;
          setField((previous) => ({
            input,
            selectedCity: previous.selectedCity === input ? input : null,
          }));
        }}
        onSuggestionSelect={(item) => {
          setField({ input: item.label, selectedCity: item.label });
        }}
        onClear={() => setField(emptyField)}
      />
    </>
  );
}

