interface ReportPeriodFormValues {
  period: {
    dateFrom: string;
    dateTo: string;
  };
}

export function ReportPeriodPicker() {
  const form = useForm<ReportPeriodFormValues>({
    mode: 'onChange',
    defaultValues: {
      period: { dateFrom: '', dateTo: '' },
    },
  });

  const today = new Date();
  today.setHours(23, 59, 59, 999);

  return (
    <FormProvider {...form}>
      <GlobalStyle />
      <FormDatePickerRange
        name="period"
        label="Период"
        format="DD.MM.YYYY"
        lang="ru"
        max={today}
        includeEdgeDates
        options={{
          max: {
            value: today.getTime(),
            message: 'Дата не может быть позже сегодняшней',
          },
        }}
      />
    </FormProvider>
  );
}

import * as React from 'react';
import { Attach } from '@daisforge/ui';

const MAX_FILE_SIZE_BYTES = 5 * 1024 * 1024;

export function RequestAttachment() {
  const [selectedFile, setSelectedFile] = React.useState<File | null>(null);

  const error = selectedFile && selectedFile.size > MAX_FILE_SIZE_BYTES
    ? `Файл «${selectedFile.name}» превышает допустимый размер 5 МБ.`
    : undefined;
  const attachedFiles = selectedFile && !error ? [selectedFile] : [];

  function handleFileChange(event: React.FormEvent<HTMLElement>) {
    const input = event.target;
    if (!(input instanceof HTMLInputElement)) return;

    const file = input.files?.item(0);
    if (!file) return;

    setSelectedFile(file);
    input.value = '';
  }

  return (
    <Attach
      type="button"
      text="Прикрепить файл к заявке"
      files={attachedFiles}
      hasAttachment={attachedFiles.length > 0}
      hideButtonOnAttach={false}
      onChange={handleFileChange}
      onClear={() => setSelectedFile(null)}
      helperText={error}
      helperTextView={error ? 'negative' : 'default'}
    />
  );
}

import * as React from 'react';
import { Attach } from '@daisforge/ui';

const MAX_FILE_SIZE = 5 * 1024 * 1024;

export function RequestAttachment() {
  const [selectedFile, setSelectedFile] = React.useState<File | null>(null);
  const isTooLarge = selectedFile !== null && selectedFile.size > MAX_FILE_SIZE;

  function handleFileChange(event: React.FormEvent<HTMLElement>) {
    const input = event.target;
    if (!(input instanceof HTMLInputElement)) {
      return;
    }

    const file = input.files?.item(0);
    if (!file) {
      return;
    }

    setSelectedFile(file);
    input.value = '';
  }

  return (
    <div>
      <Attach
        type="button"
        text={selectedFile ? 'Выбрать другой файл' : 'Прикрепить файл'}
        onChange={handleFileChange}
        helperText={isTooLarge ? 'Размер файла не должен превышать 5 МБ.' : 'Максимальный размер файла — 5 МБ.'}
        helperTextView={isTooLarge ? 'negative' : 'default'}
      />
      <div role="status">{selectedFile && <>Выбранный файл: {selectedFile.name}</>}</div>
    </div>
  );
}

