import * as React from 'react';
import { List, ListItem, Pagination } from '@daisforge/ui';
import { GlobalStyle } from '@daisforge/ui/styles';

const PAGE_SIZE = 5;
const rows = Array.from({ length: 20 }, (_, index) => ({
  id: index + 1,
  label: `Строка ${index + 1}`,
}));
const pageCount = Math.ceil(rows.length / PAGE_SIZE);

export function App() {
  const [page, setPage] = React.useState(1);
  const start = (page - 1) * PAGE_SIZE;
  const visibleRows = rows.slice(start, start + PAGE_SIZE);

  function handlePageChange(nextPage?: number) {
    if (nextPage !== undefined && Number.isInteger(nextPage) && nextPage >= 1 && nextPage <= pageCount) {
      setPage(nextPage);
    }
  }

  return (
    <>
      <GlobalStyle />
      <div style={{ display: 'grid', gap: '1rem' }}>
        <List view="default" size="s" variant="normal" hasDivider>
          {visibleRows.map(({ id, label }) => (
            <ListItem key={id}>{label}</ListItem>
          ))}
        </List>
        <nav aria-label="Страницы списка">
          <Pagination
            count={pageCount}
            value={page}
            onChange={handlePageChange}
            slots={5}
            hasPageRange
            hasPerPage={false}
            hasQuickJump={false}
          />
        </nav>
      </div>
    </>
  );
}

