const PAGE_SIZE = 5;
const rows = Array.from({ length: 20 }, (_, index) => ({
  id: index + 1,
  label: `Строка ${index + 1}`,
}));
const pageCount = Math.ceil(rows.length / PAGE_SIZE);

export function PaginatedList() {
  const [page, setPage] = React.useState(1);
  const startIndex = (page - 1) * PAGE_SIZE;
  const visibleRows = rows.slice(startIndex, startIndex + PAGE_SIZE);

  function handlePageChange(nextPage?: number) {
    if (nextPage !== undefined && nextPage >= 1 && nextPage <= pageCount) {
      setPage(nextPage);
    }
  }

  return (
    <div>
      <GlobalStyle />
      <List view="default" size="s" variant="normal">
        {visibleRows.map((row) => (
          <ListItem key={row.id}>{row.label}</ListItem>
        ))}
      </List>
      <nav aria-label="Страницы списка" style={{ marginTop: '1rem' }}>
        <Pagination
          count={pageCount}
          value={page}
          perPage={PAGE_SIZE}
          slots={5}
          hasPageRange
          onChange={handlePageChange}
        />
      </nav>
    </div>
  );
}

