import * as React from 'react';
import { Button, FormCheckbox, FormTextField } from '@daisforge/ui';
import { zodResolver } from '@hookform/resolvers/zod';
import { FormProvider, useForm, useWatch } from 'react-hook-form';
import { z } from 'zod';

function parseAmount(value: string): number {
  const normalized = value.trim().replace(',', '.');

  if (!/^(?:\d+(?:\.\d*)?|\.\d+)$/.test(normalized)) {
    return Number.NaN;
  }

  return Number(normalized);
}

const paymentSchema = z.object({
  amount: z.string().refine((value) => {
    const amount = parseAmount(value);
    return Number.isFinite(amount) && amount > 0;
  }, 'Введите сумму больше нуля'),
  purpose: z.string().trim().min(1, 'Введите назначение платежа'),
  acceptedTerms: z.boolean().refine((value) => value, 'Подтвердите согласие с условиями'),
});

type PaymentFields = z.infer<typeof paymentSchema>;

type SubmittedPayment = {
  amount: number;
  purpose: string;
};

const defaultValues: PaymentFields = {
  amount: '',
  purpose: '',
  acceptedTerms: false,
};

export function PaymentForm() {
  const form = useForm<PaymentFields>({
    defaultValues,
    resolver: zodResolver(paymentSchema),
  });
  const { control, formState, handleSubmit, reset } = form;
  const acceptedTerms = useWatch({ control, name: 'acceptedTerms' });
  const [submittedPayment, setSubmittedPayment] = React.useState<SubmittedPayment | null>(null);

  const submitPayment = handleSubmit((values) => {
    setSubmittedPayment({
      amount: parseAmount(values.amount),
      purpose: values.purpose,
    });
    reset();
  });

  return (
    <FormProvider {...form}>
      <form
        aria-label="Форма платежа"
        noValidate
        onSubmit={submitPayment}
        style={{ display: 'grid', gap: 16, maxWidth: 420 }}
      >
        <FormTextField<PaymentFields>
          name="amount"
          label="Сумма"
          inputMode="decimal"
          hasRequiredIndicator
        />
        <FormTextField<PaymentFields>
          name="purpose"
          label="Назначение платежа"
          hasRequiredIndicator
        />
        <div>
          <FormCheckbox<PaymentFields>
            name="acceptedTerms"
            label="Я согласен с условиями"
          />
          {formState.errors.acceptedTerms?.message && (
            <div role="alert">{formState.errors.acceptedTerms.message}</div>
          )}
        </div>
        <Button type="submit" view="accent" disabled={!acceptedTerms || formState.isSubmitting}>
          Оплатить
        </Button>
      </form>
      <div role="status">
        {submittedPayment && (
          <p>
            Данные платежа «{submittedPayment.purpose}» на сумму{' '}
            {String(submittedPayment.amount).replace('.', ',')} приняты.
          </p>
        )}
      </div>
    </FormProvider>
  );
}

import * as React from 'react';
import { Button, FormCheckbox, FormTextField } from '@daisforge/ui';
import { GlobalStyle } from '@daisforge/ui/styles';
import { zodResolver } from '@hookform/resolvers/zod';
import { FormProvider, useForm, useWatch } from 'react-hook-form';
import { z } from 'zod';

function parseAmount(value: string): number {
  return Number(value.trim().replace(',', '.'));
}

const paymentSchema = z.object({
  amount: z.string().refine((value) => {
    if (!/^(?:\d+(?:[.,]\d*)?|[.,]\d+)$/.test(value.trim())) {
      return false;
    }

    const amount = parseAmount(value);
    return Number.isFinite(amount) && amount > 0;
  }, 'Введите сумму больше нуля'),
  purpose: z.string().trim().min(1, 'Укажите назначение платежа'),
  agreed: z.boolean().refine((value) => value, 'Подтвердите согласие с условиями'),
});

type PaymentFormValues = z.infer<typeof paymentSchema>;

type SubmittedPayment = {
  amount: number;
  purpose: string;
};

export function PaymentForm() {
  const [submittedPayment, setSubmittedPayment] = React.useState<SubmittedPayment | null>(null);
  const form = useForm<PaymentFormValues>({
    resolver: zodResolver(paymentSchema),
    defaultValues: { amount: '', purpose: '', agreed: false },
  });
  const agreed = useWatch({ control: form.control, name: 'agreed' });
  const { errors, isSubmitting } = form.formState;

  const submitPayment = form.handleSubmit(({ amount, purpose }) => {
    setSubmittedPayment({ amount: parseAmount(amount), purpose });
    form.reset();
  });

  return (
    <FormProvider {...form}>
      <GlobalStyle />
      <form
        aria-label="Форма платежа"
        noValidate
        onSubmit={submitPayment}
        style={{ display: 'grid', gap: '16px', maxWidth: '28rem' }}
      >
        <FormTextField<PaymentFormValues> name="amount" label="Сумма" />
        <FormTextField<PaymentFormValues> name="purpose" label="Назначение платежа" />
        <FormCheckbox<PaymentFormValues> name="agreed" label="Я согласен с условиями" />
        {errors.agreed?.message && <span role="alert">{errors.agreed.message}</span>}
        <div>
          <Button type="submit" view="accent" disabled={!agreed || isSubmitting}>
            Оплатить
          </Button>
        </div>
        <div role="status">
          {submittedPayment && (
            <p>
              Данные платежа сохранены. Сумма — {submittedPayment.amount}. Назначение — {submittedPayment.purpose}.
            </p>
          )}
        </div>
      </form>
    </FormProvider>
  );
}

import * as React from 'react';
