type Recipient = {
  name: string;
  account: string;
};

type FormValues = {
  recipients: Recipient[];
};

const emptyRecipient: Recipient = { name: '', account: '' };

const recipientFields: ReadonlyArray<{
  key: keyof Recipient;
  label: string;
  requiredMessage: string;
}> = [
  { key: 'name', label: 'Имя', requiredMessage: 'Введите имя получателя' },
  { key: 'account', label: 'Счёт', requiredMessage: 'Введите счёт получателя' },
];

export function RecipientsForm() {
  const headingId = React.useId();
  const [validated, setValidated] = React.useState(false);
  const { control, handleSubmit } = useForm<FormValues>({
    defaultValues: { recipients: [emptyRecipient] },
  });
  const { fields, append, remove } = useFieldArray({
    control,
    name: 'recipients',
  });

  return (
    <>
      <GlobalStyle />
      <form
        aria-labelledby={headingId}
        noValidate
        onChange={() => setValidated(false)}
        onSubmit={handleSubmit(() => setValidated(true), () => setValidated(false))}
        style={{ display: 'grid', gap: '1rem', maxWidth: '48rem' }}
      >
        <h2 id={headingId} style={{ margin: 0 }}>Получатели</h2>

        {fields.map((recipient, index) => (
          <fieldset key={recipient.id} style={{ margin: 0, minWidth: 0 }}>
            <legend>Получатель {index + 1}</legend>
            <div style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'start', gap: '0.75rem' }}>
              {recipientFields.map(({ key, label, requiredMessage }) => (
                <div key={key} style={{ flex: '1 1 12rem', minWidth: 0 }}>
                  <Controller<FormValues>
                    control={control}
                    name={`recipients.${index}.${key}`}
                    rules={{ validate: (value) => value.trim().length > 0 || requiredMessage }}
                    render={({ field, fieldState }) => {
                      const errorId = `${headingId}-${recipient.id}-${key}-error`;

                      return (
                        <TextField
                          ref={field.ref}
                          name={field.name}
                          label={label}
                          labelPlacement="outer"
                          type="text"
                          value={field.value}
                          onBlur={field.onBlur}
                          onChange={(event) => field.onChange(event.currentTarget.value)}
                          hasRequiredIndicator
                          aria-required="true"
                          aria-invalid={fieldState.invalid}
                          aria-describedby={fieldState.error ? errorId : undefined}
                          view={fieldState.invalid ? 'negative' : 'default'}
                          leftHelper={fieldState.error && (
                            <span id={errorId} role="alert">{fieldState.error.message}</span>
                          )}
                        />
                      );
                    }}
                  />
