        ))}

        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.75rem' }}>
          <Button
            type="button"
            view="secondary"
            onClick={() => {
              append(emptyRecipient);
              setValidated(false);
            }}
          >
            Добавить получателя
