import * as React from 'react';
import { Button, FiltersActions } from '@daisforge/ui';
import { TableCanvas } from '@daisforge/ui/components/TableCanvas';
import type { ColumnConfig } from '@daisforge/ui/components/TableCanvas';
import { GlobalStyle } from '@daisforge/ui/styles';

type RequestRow = {
  id: string;
  subject: string;
  requester: string;
  status: 'Новая' | 'В работе' | 'Завершена';
};

const initialRows: RequestRow[] = [
  { id: 'З-1028', subject: 'Доступ к отчётам', requester: 'Анна Орлова', status: 'Новая' },
  { id: 'З-1027', subject: 'Обновление профиля', requester: 'Илья Соколов', status: 'В работе' },
  { id: 'З-1026', subject: 'Замена оборудования', requester: 'Мария Волкова', status: 'Новая' },
  { id: 'З-1025', subject: 'Подключение уведомлений', requester: 'Олег Кузнецов', status: 'Завершена' },
  { id: 'З-1024', subject: 'Доступ к проекту', requester: 'Елена Миронова', status: 'В работе' },
  { id: 'З-1023', subject: 'Выгрузка данных', requester: 'Павел Лебедев', status: 'Новая' },
];

const columns: readonly ColumnConfig<RequestRow>[] = [
  { key: 'id', name: 'Номер', width: 112 },
  { key: 'subject', name: 'Тема', minWidth: 224 },
  { key: 'requester', name: 'Заявитель', width: 192 },
  { key: 'status', name: 'Статус', width: 144 },
];

const getRowKey = (row: RequestRow) => row.id;

export function RequestsRegistry() {
  const [rows, setRows] = React.useState<RequestRow[]>(initialRows);
  const [query, setQuery] = React.useState('');
  const [onlyNew, setOnlyNew] = React.useState(false);
  const [selectedIds, setSelectedIds] = React.useState<ReadonlySet<string | number>>(
    () => new Set(),
  );

  const visibleRows = React.useMemo(() => {
    const term = query.trim().toLocaleLowerCase('ru');

    return rows.filter((row) => {
      if (onlyNew && row.status !== 'Новая') return false;

      return [row.id, row.subject, row.requester].some((value) =>
        value.toLocaleLowerCase('ru').includes(term),
      );
    });
  }, [rows, query, onlyNew]);

  const canCompleteSelection = visibleRows.some(
    (row) => selectedIds.has(row.id) && row.status !== 'Завершена',
  );

  function clearSelection() {
    setSelectedIds(new Set());
  }

  function changeQuery(value: string) {
    setQuery(value);
    clearSelection();
  }

  function resetFilters() {
    setOnlyNew(false);
    changeQuery('');
  }

  function completeSelection() {
    setRows((currentRows) =>
      currentRows.map<RequestRow>((row) =>
        selectedIds.has(row.id) && row.status !== 'Завершена'
          ? { ...row, status: 'Завершена' }
          : row,
      ),
    );
    clearSelection();
  }

  return (
    <section aria-label="Реестр заявок" style={{ padding: 24, minWidth: 0 }}>
      <GlobalStyle />
      <h1 style={{ margin: '0 0 20px' }}>Реестр заявок</h1>

      <div role="group" aria-label="Фильтры заявок" style={{ marginBottom: 12 }}>
        <FiltersActions
          mainBlock={
            <div style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: 12 }}>
              <FiltersActions.TextFieldSearch
                aria-label="Поиск по номеру, теме или заявителю"
                placeholder="Номер, тема или заявитель"
                autoComplete="off"
                value={query}
                onChange={(event) => changeQuery(event.currentTarget.value)}
                onClear={() => changeQuery('')}
              />
              <FiltersActions.SwitcherFilter
                label="Только новые"
                checked={onlyNew}
                onChange={(event) => {
                  setOnlyNew(event.currentTarget.checked);
                  clearSelection();
                }}
              />
            </div>
          }
          activeButtonsBlock={
            <Button
              type="button"
              view="secondary"
              size="s"
              disabled={query === '' && !onlyNew}
              onClick={resetFilters}
            >
              Сбросить фильтры
            </Button>
          }
        />
      </div>

      <TableCanvas
        rows={visibleRows}
        columnConfig={columns}
        tableConfig={{
          containerStyle: { height: 480, width: '100%' },
          emptyState: { enabled: true, title: 'Заявки не найдены' },
          selecting: {
            state: [selectedIds, setSelectedIds],
            rowKeyGetter: getRowKey,
            showDefault: true,
          },
          controlBlock: {
            massActionPanel: {
              buttons: [
                {
                  type: 'button',
                  text: 'Завершить заявки',
                  view: 'accent',
                  disabled: !canCompleteSelection,
                  onClick: completeSelection,
                },
                {
                  type: 'button',
                  text: 'Снять выбор',
                  view: 'secondary',
                  onClick: clearSelection,
                },
              ],
            },
          },
        }}
      />
    </section>
  );
}

import * as React from 'react';
import { Button, Combobox, FiltersActions, TextFieldSearch } from '@daisforge/ui';
import { TableCanvas } from '@daisforge/ui/components/TableCanvas';
import type { ColumnConfig } from '@daisforge/ui/components/TableCanvas';
import { GlobalStyle } from '@daisforge/ui/styles';

type RequestStatus = 'Новая' | 'В работе' | 'Закрыта';

type RequestRow = {
  id: string;
  subject: string;
  requester: string;
  status: RequestStatus;
};

type Filters = {
  query: string;
  statuses: string[];
};

const initialFilters: Filters = { query: '', statuses: [] };

const statusOptions: { value: RequestStatus; label: string }[] = [
  { value: 'Новая', label: 'Новая' },
  { value: 'В работе', label: 'В работе' },
  { value: 'Закрыта', label: 'Закрыта' },
];

const initialRequests: RequestRow[] = [
  { id: 'ЗА-1048', subject: 'Доступ к отчётам', requester: 'Анна Орлова', status: 'Новая' },
  { id: 'ЗА-1047', subject: 'Обновление справочника', requester: 'Илья Смирнов', status: 'В работе' },
  { id: 'ЗА-1046', subject: 'Замена рабочего ноутбука', requester: 'Мария Лебедева', status: 'Новая' },
  { id: 'ЗА-1045', subject: 'Подключение к проекту', requester: 'Павел Волков', status: 'Закрыта' },
  { id: 'ЗА-1044', subject: 'Проверка прав доступа', requester: 'Елена Кузнецова', status: 'В работе' },
  { id: 'ЗА-1043', subject: 'Изменение контактных данных', requester: 'Денис Морозов', status: 'Закрыта' },
  { id: 'ЗА-1042', subject: 'Настройка уведомлений', requester: 'Софья Попова', status: 'Новая' },
];

const columns: readonly ColumnConfig<RequestRow>[] = [
  { key: 'id', name: 'Номер', width: 112 },
  { key: 'subject', name: 'Тема заявки', minWidth: 240 },
  { key: 'requester', name: 'Заявитель', minWidth: 180 },
  { key: 'status', name: 'Статус', width: 128 },
];

export function RequestRegistry() {
  const headingId = React.useId();
  const [requests, setRequests] = React.useState(initialRequests);
  const [filters, setFilters] = React.useState(initialFilters);
  const selection = React.useState<ReadonlySet<string | number>>(() => new Set());
  const [selectedIds, setSelectedIds] = selection;
  const [notice, setNotice] = React.useState('');

  const visibleRequests = React.useMemo(() => {
    const query = filters.query.trim().toLocaleLowerCase('ru');

    return requests.filter((request) => {
      const matchesStatus = filters.statuses.length === 0 || filters.statuses.includes(request.status);
      const matchesQuery = [request.id, request.subject, request.requester].some(
        (field) => field.toLocaleLowerCase('ru').includes(query),
      );

      return matchesStatus && matchesQuery;
    });
  }, [filters, requests]);

  const selectedRequests = visibleRequests.filter((request) => selectedIds.has(request.id));

  function updateFilters(changes: Partial<Filters>) {
    setFilters((current) => ({ ...current, ...changes }));
    setSelectedIds(new Set());
    setNotice('');
  }

  function changeSelectedStatus(status: RequestStatus) {
    const idsToUpdate = new Set(
      selectedRequests.filter((request) => request.status !== status).map((request) => request.id),
    );

    if (idsToUpdate.size === 0) {
      return;
    }

    setRequests((current) => current.map((request) =>
      idsToUpdate.has(request.id) ? { ...request, status } : request,
    ));
    setSelectedIds(new Set());
    setNotice(`Статус изменён у ${idsToUpdate.size} из ${selectedRequests.length} выбранных заявок.`);
  }

  return (
    <section aria-labelledby={headingId} style={{ maxWidth: 1200, margin: '0 auto', padding: 24 }}>
      <GlobalStyle />
      <h1 id={headingId} style={{ margin: '0 0 16px' }}>Реестр заявок</h1>

      <div role="group" aria-label="Фильтры заявок">
        <FiltersActions
          mainBlock={
            <div style={{ display: 'flex', alignItems: 'center', flexWrap: 'wrap', gap: 8 }}>
              <div style={{ width: 320, maxWidth: '100%' }}>
                <TextFieldSearch
                  size="s"
                  aria-label="Поиск заявок"
                  placeholder="Номер, тема или заявитель"
                  value={filters.query}
                  onChange={(event) => updateFilters({ query: event.target.value })}
                  onClear={() => updateFilters({ query: '' })}
                  autoComplete="off"
                />
              </div>
              <div style={{ width: 180, maxWidth: '100%' }}>
                <Combobox
                  size="s"
                  multiple
                  isTargetAmount
                  aria-label="Статус заявки"
                  placeholder="Статус"
                  items={statusOptions}
                  value={filters.statuses}
                  onChange={(statuses) => updateFilters({ statuses })}
                />
              </div>
              <Button
                type="button"
                size="s"
                view="secondary"
                disabled={filters.query === '' && filters.statuses.length === 0}
                onClick={() => updateFilters(initialFilters)}
              >
                Сбросить фильтры
              </Button>
            </div>
          }
        />
      </div>

      <p role="status" style={{ margin: '12px 0', fontSize: 14 }}>
        Показано заявок: {visibleRequests.length} из {requests.length}.
        {notice && ` ${notice}`}
      </p>

      <TableCanvas
        rows={visibleRequests}
        columnConfig={columns}
        tableConfig={{
          containerStyle: { height: 460, width: '100%' },
          selecting: {
            showDefault: true,
            state: selection,
            rowKeyGetter: (row) => row.id,
          },
          emptyState: {
            enabled: true,
            size: 's',
            variant: 'not-found',
            title: 'Заявки не найдены',
            subtitle: 'Измените поисковый запрос или сбросьте фильтры.',
          },
          controlBlock: {
            massActionPanel: {
              buttons: [
                {
                  type: 'button',
                  text: 'Взять в работу',
                  view: 'accent',
                  disabled: !selectedRequests.some((request) => request.status !== 'В работе'),
                  onClick: () => changeSelectedStatus('В работе'),
                },
                {
                  type: 'button',
                  text: 'Закрыть заявки',
                  view: 'secondary',
                  disabled: !selectedRequests.some((request) => request.status !== 'Закрыта'),
                  onClick: () => changeSelectedStatus('Закрыта'),
                },
              ],
            },
          },
        }}
      />
    </section>
  );
}

import * as React from 'react';
