type Contract = {
  number: string;
};

const initialContract: Contract = { number: '1042' };

export function DeleteContract(): React.JSX.Element {
  const [contract, setContract] = React.useState<Contract | null>(initialContract);
  const [isConfirmationOpen, setIsConfirmationOpen] = React.useState(false);

  function closeConfirmation() {
    setIsConfirmationOpen(false);
  }

  function confirmDeletion() {
    setContract(null);
    closeConfirmation();
  }

  return (
    <>
      <GlobalStyle />
      {contract && (
        <div>
          <p>Договор № {contract.number}</p>
          <Button type="button" view="negative" onClick={() => setIsConfirmationOpen(true)}>
            Удалить договор
          </Button>
        </div>
      )}
      <div role="status">{contract === null && 'Договор удалён.'}</div>
      {contract && (
        <ModalDFConfirmation
          opened={isConfirmationOpen}
          onClose={closeConfirmation}
          view="negative"
          hasClose={false}
          content={{
            header: `Удалить договор № ${contract.number}?`,
            body: 'После удаления восстановить договор будет невозможно.',
            secondaryButton: {
              type: 'button',
              text: 'Отмена',
              onClick: closeConfirmation,
            },
            mainButton: {
              type: 'button',
              text: 'Удалить',
              view: 'negative',
              onClick: confirmDeletion,
            },
          }}
        />
      )}
    </>
  );
}

