  'АО «Вектор»',
  'ООО «Горизонт»',
  'ООО «Меридиан»',
  'АО «Спектр»',
];

const STATUS_SEQUENCE: readonly DealStatus[] = [
  'completed', 'pending', 'completed', 'cancelled', 'pending',
];

const dateFormat = new Intl.DateTimeFormat('ru-RU', {
  day: '2-digit',
  month: '2-digit',
