});

const currencyFormat = new Intl.NumberFormat('ru-RU', {
  style: 'currency',
  currency: 'RUB',
  maximumFractionDigits: 0,
});

const deals: Deal[] = Array.from({ length: 60 }, (_, index): Deal => ({
  id: `СД-${2026001 + index}`,
  date: dateFormat.format(new Date(Date.UTC(2026, 8, index + 1))),
  counterparty: COUNTERPARTIES[index % COUNTERPARTIES.length] ?? 'ООО «Альтаир»',
  amount: 85_000 + ((index * 19) % 83) * 12_500,
  status: STATUS_SEQUENCE[(index + Math.floor(index / 5)) % STATUS_SEQUENCE.length] ?? 'pending',
