        <Canvas.Badge
          text={STATUS_LABELS[row.status]}
          view={STATUS_VIEWS[row.status]}
          pilled
        />
      </Canvas.Container>
    ),
  },
];

export function DealRegistry() {
  const [opened, setOpened] = React.useState(false);

  const close = () => setOpened(false);

  return (
    <>
      <GlobalStyle />
      <Button type="button" view="accent" aria-haspopup="dialog" onClick={() => setOpened(true)}>
        Реестр сделок
      </Button>
