            minHeight: 0,
          }}
        >
          <ModalDF.Header
            title="Реестр сделок"
            subTitle={`Сентябрь и октябрь 2026 · ${deals.length} сделок`}
          />
          <ModalDF.Content style={{ minWidth: 0, minHeight: 0, overflow: 'hidden' }}>
