const dealTemplates: ReadonlyArray<Pick<Deal, 'counterparty' | 'status'>> = [
  { counterparty: 'ООО «Горизонт»', status: 'В работе' },
  { counterparty: 'АО «Север»', status: 'Завершена' },
  { counterparty: 'ООО «Вектор»', status: 'Завершена' },
  { counterparty: 'АО «Контур»', status: 'В работе' },
  { counterparty: 'ООО «Маяк»', status: 'Отменена' },
];

const dateFormatter = new Intl.DateTimeFormat('ru-RU', {
  day: '2-digit',
  month: '2-digit',
  year: 'numeric',
  timeZone: 'UTC',
});

const rubles = new Intl.NumberFormat('ru-RU', {
  style: 'currency',
  currency: 'RUB',
  maximumFractionDigits: 0,
});

const deals: Deal[] = Array.from({ length: 12 }, (_, batch) =>
  dealTemplates.map((template, index): Deal => {
    const number = batch * dealTemplates.length + index + 1;
    return {
      ...template,
      id: `СД-${String(number).padStart(4, '0')}`,
      date: dateFormatter.format(Date.UTC(2026, 0, number)),
      amount: 85_000 + batch * 37_500 + index * 12_400,
    };
  }),
).flat();

const total = deals.reduce((sum, deal) => sum + deal.amount, 0);

const columns: readonly ColumnConfig<Deal>[] = [
  { key: 'id', name: '№ сделки', width: 130 },
  { key: 'date', name: 'Дата', width: 128 },
  { key: 'counterparty', name: 'Контрагент', minWidth: 200 },
  {
    key: 'amount',
    name: 'Сумма',
    width: 160,
    contentFormat: {
      alignContent: 'right',
      customFormat: (value) => rubles.format(Number(value)),
    },
  },
  {
    key: 'status',
    name: 'Статус',
    width: 156,
    copyData: (row) => row.status,
    renderCell: ({ row, theme }) => (
      <Canvas.Container
        alignItems="center"
        padding={{ left: theme.cellHorizontalPadding, right: theme.cellHorizontalPadding }}
      >
        <Canvas.Badge text={row.status} view={statusViews[row.status]} pilled />
      </Canvas.Container>
    ),
  },
];

export function DealRegistry() {
  const [opened, setOpened] = React.useState(false);
  const close = () => setOpened(false);

  return (
    <>
      <GlobalStyle />
      <Button
