type Payment = {
  date: string;
  amount: number;
  status: 'Оплачен' | 'К оплате';
};

const contractNumber = 'ДГ-2026-0148';
const payments: Payment[] = [
  { date: '15.09.2026', amount: 12500, status: 'Оплачен' },
  { date: '15.10.2026', amount: 12500, status: 'Оплачен' },
  { date: '15.11.2026', amount: 12500, status: 'Оплачен' },
  { date: '15.12.2026', amount: 12500, status: 'К оплате' },
];

const columns: readonly ColumnConfig<Payment>[] = [
  { key: 'date', name: 'Дата платежа', minWidth: 112 },
  {
    key: 'amount',
    name: 'Сумма, ₽',
