    contentFormat: {
      type: 'number',
      locales: ['ru-RU'],
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
      alignContent: 'right',
    },
  },
  { key: 'status', name: 'Статус', minWidth: 90 },
];

const tableConfig = { containerStyle: { width: '100%', height: '220px' } };

function downloadPayments(): void {
  const lines = [
    'Номер договора;Дата платежа;Сумма, ₽;Статус',
    ...payments.map(({ date, amount, status }) =>
      [contractNumber, date, amount.toFixed(2).replace('.', ','), status].join(';'),
    ),
  ];
  const file = new Blob(['\uFEFF', lines.join('\r\n')], {
    type: 'text/csv;charset=utf-8',
  });
  const url = URL.createObjectURL(file);
  const link = document.createElement('a');
  link.href = url;
  link.download = `Платежи-${contractNumber}.csv`;
  document.body.appendChild(link);
  try {
    link.click();
  } finally {
    link.remove();
    window.setTimeout(() => URL.revokeObjectURL(url), 1000);
  }
}

