import * as React from 'react';
import { Button, IconButton } from '@daisforge/ui';
import { GlobalStyle } from '@daisforge/ui/styles';

type ListItem = {
  id: number;
  name: string;
};

const initialItems: readonly ListItem[] = [
  { id: 1, name: 'Запись 1' },
  { id: 2, name: 'Запись 2' },
];

export function ListActions() {
  const settingsId = React.useId();
  const localItems = React.useRef(initialItems);
  const [items, setItems] = React.useState(initialItems);
  const [settingsOpen, setSettingsOpen] = React.useState(false);
  const [newestFirst, setNewestFirst] = React.useState(false);
  const [lastRefresh, setLastRefresh] = React.useState<Date | null>(null);

  function createItem() {
    const id = localItems.current.length + 1;
    const nextItems = [...localItems.current, { id, name: `Запись ${id}` }];
    localItems.current = nextItems;
    setItems(nextItems);
  }

  function refreshItems() {
    setItems([...localItems.current]);
    setLastRefresh(new Date());
  }

  const visibleItems = newestFirst ? [...items].reverse() : items;

  return (
    <section aria-label="Список записей">
      <GlobalStyle />
      <div
        role="group"
        aria-label="Действия со списком"
        style={{ display: 'flex', alignItems: 'center', flexWrap: 'nowrap', gap: 8, overflowX: 'auto' }}
      >
        <Button type="button" size="s" view="accent" onClick={createItem}>
          Создать
        </Button>
        <Button type="button" size="s" view="secondary" onClick={refreshItems}>
          Обновить
        </Button>
        <IconButton
          type="button"
          size="s"
          view="secondary"
          aria-label="Настройки"
          title="Настройки"
          aria-expanded={settingsOpen}
          aria-controls={settingsId}
          onClick={() => setSettingsOpen((open) => !open)}
        >
          <svg
            width="20"
            height="20"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            aria-hidden="true"
            focusable="false"
          >
            <path d="M4 6h8m4 0h4M4 12h3m4 0h9M4 18h11m4 0h1M12 4v4M7 10v4m8 2v4" />
          </svg>
        </IconButton>
      </div>

      <div id={settingsId} hidden={!settingsOpen} style={{ marginTop: 8 }}>
        <label>
          <input
            type="checkbox"
            checked={newestFirst}
            onChange={(event) => setNewestFirst(event.currentTarget.checked)}
          />
          Сначала новые записи
        </label>
      </div>

      <ul>
        {visibleItems.map((item) => (
          <li key={item.id}>{item.name}</li>
        ))}
      </ul>

      <div role="status">
        {lastRefresh && (
          <>
            Список обновлён в{' '}
            <time dateTime={lastRefresh.toISOString()}>{lastRefresh.toLocaleTimeString('ru-RU')}</time>
          </>
        )}
      </div>
    </section>
  );
}

