  'Уфа',
  'Ростов-на-Дону',
];

const citySuggestions = cities.map((city) => ({ label: city, value: city }));

export function CityAutocomplete() {
  const [inputValue, setInputValue] = React.useState('');
  const [selectedCity, setSelectedCity] = React.useState<string | null>(null);
  const query = inputValue.trim().toLocaleLowerCase('ru-RU');

  return (
    <>
      <GlobalStyle />
      <Autocomplete
        label="Город"
        placeholder="Начните вводить название города"
        autoComplete="off"
        value={inputValue}
        threshold={1}
        suggestions={citySuggestions}
        filter={(item) =>
          selectedCity === null &&
          query.length > 0 &&
          item.label.toLocaleLowerCase('ru-RU').includes(query)
        }
        onChange={(event) => {
          const nextValue = event.currentTarget.value;
          setInputValue(nextValue);
          setSelectedCity((city) => (city === nextValue ? city : null));
        }}
        onSuggestionSelect={(item) => {
          setInputValue(item.label);
          setSelectedCity(item.label);
        }}
        onClear={() => {
          setInputValue('');
          setSelectedCity(null);
        }}
      />
    </>
  );
}

