import * as React from 'react';
import { DatePickerRange } from '@daisforge/ui';

type PeriodEndpoint = Date | '';
type ReportPeriod = [start: PeriodEndpoint, end: PeriodEndpoint];

function endOfToday(): Date {
  const today = new Date();
  today.setHours(23, 59, 59, 999);
  return today;
}

function parseEndpoint(value: unknown): PeriodEndpoint | undefined {
  if (value === '' || value === null || value === undefined) {
    return '';
  }

  if (value instanceof Date) {
    return Number.isFinite(value.getTime()) ? value : undefined;
  }

  if (typeof value !== 'string' || !/^\d{2}\.\d{2}\.\d{4}$/.test(value)) {
    return undefined;
  }

  const day = Number(value.slice(0, 2));
  const month = Number(value.slice(3, 5)) - 1;
  const year = Number(value.slice(6));
  const date = new Date(0);
  date.setFullYear(year, month, day);
  date.setHours(0, 0, 0, 0);

  if (date.getFullYear() !== year || date.getMonth() !== month || date.getDate() !== day) {
    return undefined;
  }

  return date;
}

export function ReportPeriodPicker() {
  const [period, setPeriod] = React.useState<ReportPeriod>(['', '']);

  function commitEndpoint(endpoint: 'start' | 'end', value: unknown) {
    const date = parseEndpoint(value);
    if (date === undefined || (date !== '' && date > endOfToday())) {
      return;
    }

    setPeriod(([start, end]) => (endpoint === 'start' ? [date, end] : [start, date]));
  }

  return (
    <DatePickerRange
      label="Период"
      format="DD.MM.YYYY"
      lang="ru"
      max={endOfToday()}
      includeEdgeDates
      value={period}
      onCommitFirstDate={(value) => commitEndpoint('start', value)}
      onCommitSecondDate={(value) => commitEndpoint('end', value)}
    />
  );
}

