const MAX_FILE_SIZE = 5 * 1024 * 1024;

export function RequestAttachment() {
  const [file, setFile] = React.useState<File | null>(null);
  const isTooLarge = file !== null && file.size > MAX_FILE_SIZE;

  function handleChange(event: React.ChangeEvent<HTMLInputElement>) {
    const nextFile = event.currentTarget.files?.item(0);
    if (nextFile) {
      setFile(nextFile);
    }
  }

  return (
    <Attach
      type="button"
      text="Прикрепить файл к заявке"
      files={file ? [file] : []}
      onChange={handleChange}
      onClear={() => setFile(null)}
      hideButtonOnAttach={false}
      helperText={isTooLarge ? 'Размер файла превышает 5 МБ.' : ''}
      helperTextView={isTooLarge ? 'negative' : 'default'}
    />
  );
}

import * as React from 'react';
import { Attach } from '@daisforge/ui';
import { GlobalStyle } from '@daisforge/ui/styles';

const MAX_FILE_SIZE = 5 * 1024 * 1024;

export function ApplicationAttachment() {
  const [selectedFile, setSelectedFile] = React.useState<File | null>(null);
  const isTooLarge = selectedFile !== null && selectedFile.size > MAX_FILE_SIZE;

  function handleFileChange(event: React.FormEvent<HTMLElement>) {
    const input = event.target;
    if (!(input instanceof HTMLInputElement)) {
      return;
    }

    const file = input.files?.item(0);
    if (!file) {
      return;
    }

    setSelectedFile(file);
    input.value = '';
  }

  return (
    <>
      <GlobalStyle />
      <Attach
        text="Выбрать вложение к заявке"
        onChange={handleFileChange}
        helperText={isTooLarge ? 'Размер файла превышает 5 МБ.' : undefined}
        helperTextView={isTooLarge ? 'negative' : 'default'}
      />
      <div role="status">
        {selectedFile && <p>Выбранный файл: {selectedFile.name}</p>}
      </div>
    </>
  );
}

