    answer: 'Укажите адрес при оформлении заказа. Доступные даты доставки появятся перед подтверждением.',
  },
  {
    id: 'tracking',
    question: 'Где посмотреть статус заказа?',
    answer: 'Откройте раздел «Мои заказы» в личном кабинете и выберите нужный заказ.',
  },
  {
    id: 'return',
    question: 'Как вернуть товар?',
    answer: 'Откройте заказ в личном кабинете, выберите товар и заполните заявку на возврат.',
  },
];

export function FrequentlyAskedQuestions() {
  const headingId = React.useId();
  const [openIndex, setOpenIndex] = React.useState<number | null>(null);

  function handleChange(index?: number, isOpen?: boolean) {
    if (index === undefined || isOpen === undefined) {
      return;
    }

    setOpenIndex((current) => {
      if (isOpen) {
        return index;
      }

      return current === index ? null : current;
    });
  }

  return (
    <section aria-labelledby={headingId}>
      <h2 id={headingId}>Частые вопросы</h2>
      <Accordion singleActive onChange={handleChange}>
        {questions.map(({ id, question, answer }, index) => (
          <AccordionItem
            key={id}
            eventKey={index}
            title={question}
            type="arrow"
            titleProps={{ 'aria-expanded': openIndex === index }}
          >
            {answer}
          </AccordionItem>
        ))}
      </Accordion>
    </section>
  );
}

