import * as React from 'react';
import { Button, FormDatePicker, FormSelect, FormTextField } from '@daisforge/ui';
import { GlobalStyle } from '@daisforge/ui/styles';
import { FormProvider, useForm } from 'react-hook-form';

interface ProfileValues {
  fullName: string;
  email: string;
  birthDate: string;
  city: string;
}

const cities = [
  { value: 'moscow', label: 'Москва' },
  { value: 'saint-petersburg', label: 'Санкт-Петербург' },
  { value: 'kazan', label: 'Казань' },
  { value: 'yekaterinburg', label: 'Екатеринбург' },
  { value: 'novosibirsk', label: 'Новосибирск' },
];

const emailPattern = /^[^\s@.]+(?:\.[^\s@.]+)*@(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/i;

export function UserProfileForm() {
  const form = useForm<ProfileValues>({
    defaultValues: {
      fullName: '',
      email: '',
      birthDate: '',
      city: '',
    },
  });
  const [savedProfile, setSavedProfile] = React.useState<ProfileValues | null>(null);
  const current = form.watch();
  const isSaved = savedProfile !== null
    && current.fullName.trim() === savedProfile.fullName
    && current.email.trim() === savedProfile.email
    && current.birthDate === savedProfile.birthDate
    && current.city === savedProfile.city;

  const saveProfile = form.handleSubmit((values) => {
    setSavedProfile({
      fullName: values.fullName.trim(),
      email: values.email.trim(),
      birthDate: values.birthDate,
      city: values.city,
    });
  });

  return (
    <FormProvider {...form}>
      <GlobalStyle />
      <form
        aria-label="Профиль пользователя"
        noValidate
        onSubmit={saveProfile}
        style={{ display: 'grid', gap: '1rem', maxWidth: '28rem' }}
      >
        <FormTextField<ProfileValues>
          name="fullName"
          label="ФИО"
          labelPlacement="outer"
          autoComplete="name"
          hasRequiredIndicator
          options={{
            required: 'Введите ФИО',
            validate: (value: string) => value.trim().length > 0 || 'Введите ФИО',
          }}
        />
        <FormTextField<ProfileValues>
          name="email"
          label="E-mail"
          labelPlacement="outer"
          type="email"
          autoComplete="email"
          hasRequiredIndicator
          options={{
            required: 'Введите e-mail',
            validate: (value: string) => {
              const email = value.trim();
              if (email.length === 0) return 'Введите e-mail';
              return emailPattern.test(email) || 'Введите корректный e-mail';
            },
          }}
        />
        <FormDatePicker<ProfileValues>
          name="birthDate"
          label="Дата рождения"
          labelPlacement="outer"
          placeholder="ДД.ММ.ГГГГ"
          hasRequiredIndicator
          closeAfterDateSelect
          invalidFormatMessage="Введите корректную дату рождения"
          options={{ required: 'Укажите дату рождения' }}
        />
        <FormSelect<ProfileValues>
          name="city"
          label="Город"
          labelPlacement="outer"
          placeholder="Выберите город"
          items={cities}
          mode="radio"
          type="button"
          hasRequiredIndicator
          options={{ required: 'Выберите город' }}
        />
        <div>
          <Button type="submit" view="accent">Сохранить</Button>
        </div>
        <div role="status">{isSaved ? 'Профиль сохранён' : null}</div>
      </form>
    </FormProvider>
  );
}

import * as React from 'react';
import { Button, FormCheckbox, FormNumberFormat, FormTextField } from '@daisforge/ui';
import { GlobalStyle } from '@daisforge/ui/styles';
import { zodResolver } from '@hookform/resolvers/zod';
import { FormProvider, useForm, useWatch } from 'react-hook-form';
import { z } from 'zod';

const paymentSchema = z.object({
  amount: z.string().refine((value) => {
    const amount = Number(value.replace(',', '.'));
    return Number.isFinite(amount) && amount > 0;
  }, 'Введите положительную сумму'),
  purpose: z.string().trim().min(1, 'Укажите назначение платежа'),
  acceptedTerms: z.boolean().refine((accepted) => accepted, 'Подтвердите согласие с условиями'),
});

type PaymentFields = z.infer<typeof paymentSchema>;

type SubmittedPayment = {
  amount: number;
  purpose: string;
};

const defaultValues: PaymentFields = {
  amount: '',
  purpose: '',
  acceptedTerms: false,
};

export function PaymentForm() {
  const form = useForm<PaymentFields>({
    defaultValues,
    resolver: zodResolver(paymentSchema),
  });
  const acceptedTerms = useWatch({ control: form.control, name: 'acceptedTerms' });
  const { errors, isSubmitting } = form.formState;
  const [submittedPayment, setSubmittedPayment] = React.useState<SubmittedPayment | null>(null);

  const submitPayment = form.handleSubmit(({ amount, purpose }) => {
    setSubmittedPayment({ amount: Number(amount.replace(',', '.')), purpose });
    form.reset(defaultValues);
  });

  return (
    <FormProvider {...form}>
      <GlobalStyle />
      <form
        aria-label="Форма платежа"
        noValidate
        onSubmit={submitPayment}
        style={{ display: 'grid', gap: 16, maxWidth: 440 }}
      >
        <FormNumberFormat<PaymentFields>
          name="amount"
          label="Сумма"
          size="s"
          decimalSeparator="," 
          thousandSeparator={false}
          allowNegative={false}
          view={errors.amount ? 'negative' : 'default'}
          leftHelper={errors.amount?.message}
        />
        <FormTextField<PaymentFields>
          name="purpose"
          label="Назначение платежа"
          size="s"
          view={errors.purpose ? 'negative' : 'default'}
          leftHelper={errors.purpose?.message}
        />
        <div>
          <FormCheckbox<PaymentFields>
            name="acceptedTerms"
            label="Я согласен с условиями оплаты"
            size="m"
          />
          {errors.acceptedTerms?.message && <p role="alert">{errors.acceptedTerms.message}</p>}
        </div>
        <div>
          <Button type="submit" size="s" view="accent" disabled={!acceptedTerms || isSubmitting}>
            Оплатить
          </Button>
        </div>
        <div role="status">
          {submittedPayment && (
            <>
              <div>Данные платежа сохранены локально.</div>
              <div>Сумма: {String(submittedPayment.amount).replace('.', ',')}</div>
              <div>Назначение платежа: {submittedPayment.purpose}</div>
            </>
          )}
        </div>
      </form>
    </FormProvider>
  );
}

import * as React from 'react';
import { Button, Checkbox, TextField } from '@daisforge/ui';
import { GlobalStyle } from '@daisforge/ui/styles';
import { zodResolver } from '@hookform/resolvers/zod';
import { Controller, useForm } from 'react-hook-form';
import { z } from 'zod';

function parseAmount(value: string): number {
  const normalized = value.trim().replace(',', '.');

  if (!/^\+?(?:\d+(?:\.\d*)?|\.\d+)$/.test(normalized)) {
    return Number.NaN;
  }

  return Number(normalized);
}

const paymentSchema = z.object({
  amount: z.string().refine((value) => {
    const amount = parseAmount(value);
    return Number.isFinite(amount) && amount > 0;
  }, { message: 'Введите сумму больше нуля' }),
  purpose: z.string().trim().min(1, 'Укажите назначение платежа'),
  acceptedTerms: z.boolean().refine((accepted) => accepted, {
    message: 'Подтвердите согласие с условиями',
  }),
});

type PaymentFields = z.infer<typeof paymentSchema>;
type SubmittedPayment = Omit<PaymentFields, 'amount'> & { amount: number };

export function PaymentForm() {
  const id = React.useId();
  const amountErrorId = `${id}-amount-error`;
  const purposeErrorId = `${id}-purpose-error`;
  const termsErrorId = `${id}-terms-error`;
  const [payment, setPayment] = React.useState<SubmittedPayment | null>(null);
  const { control, handleSubmit, watch, formState: { isSubmitting } } = useForm<PaymentFields>({
    resolver: zodResolver(paymentSchema),
    mode: 'onTouched',
    defaultValues: { amount: '', purpose: '', acceptedTerms: false },
  });
  const acceptedTerms = watch('acceptedTerms');

  return (
    <>
      <GlobalStyle />
      <form
        aria-label="Форма платежа"
        noValidate
        onChange={() => setPayment(null)}
        onSubmit={handleSubmit((values) => {
          setPayment({ ...values, amount: parseAmount(values.amount) });
        })}
        style={{ display: 'grid', gap: '16px', maxWidth: '420px' }}
      >
        <Controller
          control={control}
          name="amount"
          render={({ field, fieldState: { error } }) => (
            <TextField
              {...field}
              size="s"
              label="Сумма"
              inputMode="decimal"
              aria-required="true"
              aria-invalid={Boolean(error)}
              aria-describedby={error ? amountErrorId : undefined}
              view={error ? 'negative' : 'default'}
              leftHelper={error && <span id={amountErrorId} role="alert">{error.message}</span>}
            />
          )}
        />

        <Controller
          control={control}
          name="purpose"
          render={({ field, fieldState: { error } }) => (
            <TextField
              {...field}
              size="s"
              label="Назначение платежа"
              aria-required="true"
              aria-invalid={Boolean(error)}
              aria-describedby={error ? purposeErrorId : undefined}
              view={error ? 'negative' : 'default'}
              leftHelper={error && <span id={purposeErrorId} role="alert">{error.message}</span>}
            />
          )}
        />

        <Controller
          control={control}
          name="acceptedTerms"
          render={({ field, fieldState: { error } }) => (
            <div>
              <Checkbox
                ref={field.ref}
                name={field.name}
                checked={field.value}
                onBlur={field.onBlur}
                onChange={(event) => field.onChange(event.currentTarget.checked)}
                label="Я согласен с условиями оплаты"
                aria-required="true"
                aria-invalid={Boolean(error)}
                aria-describedby={error ? termsErrorId : undefined}
                view={error ? 'negative' : 'default'}
              />
              {error && <div id={termsErrorId} role="alert">{error.message}</div>}
            </div>
          )}
        />

        <div>
          <Button type="submit" size="s" disabled={!acceptedTerms || isSubmitting}>
            Оплатить
          </Button>
        </div>

        {payment && (
          <div role="status">
            Данные платежа приняты. Сумма {payment.amount}. Назначение платежа: {payment.purpose}.
          </div>
        )}
      </form>
    </>
  );
}

import * as React from 'react';
