import * as React from 'react';
import { Controller, useFieldArray, useForm } from 'react-hook-form';
import { Button, TextField } from '@daisforge/ui';
import { GlobalStyle } from '@daisforge/ui/styles';

type Recipient = {
  name: string;
  account: string;
};

type FormValues = {
  recipients: Recipient[];
};

type RecipientFieldPath = `recipients.${number}.${keyof Recipient}`;

const recipientFields: ReadonlyArray<{
  key: keyof Recipient;
  label: string;
  requiredMessage: string;
}> = [
  { key: 'name', label: 'Имя', requiredMessage: 'Введите имя получателя' },
  { key: 'account', label: 'Счёт', requiredMessage: 'Введите счёт получателя' },
];

export function RecipientsForm() {
  const [isChecked, setIsChecked] = React.useState(false);
  const { control, handleSubmit } = useForm<FormValues>({
    defaultValues: { recipients: [{ name: '', account: '' }] },
  });
  const { fields, append, remove } = useFieldArray({
    control,
    name: 'recipients',
  });

  return (
    <>
      <GlobalStyle />
      <form
        aria-label="Список получателей"
        noValidate
        onSubmit={handleSubmit(
          () => setIsChecked(true),
          () => setIsChecked(false),
        )}
        style={{ display: 'grid', gap: 16, maxWidth: 720 }}
      >
        {fields.map((recipient, index) => (
          <fieldset
            key={recipient.id}
            style={{
              display: 'flex',
              flexWrap: 'wrap',
              alignItems: 'flex-start',
              gap: 12,
              minWidth: 0,
            }}
          >
            <legend>Получатель {index + 1}</legend>
            {recipientFields.map(({ key, label, requiredMessage }) => {
              const name: RecipientFieldPath = `recipients.${index}.${key}`;

              return (
                <div key={key} style={{ flex: '1 1 200px', minWidth: 0 }}>
                  <Controller
                    control={control}
                    name={name}
                    rules={{
                      required: requiredMessage,
                      validate: (value) => value.trim().length > 0 || requiredMessage,
                    }}
                    render={({ field, fieldState }) => (
                      <TextField
                        name={field.name}
                        ref={field.ref}
                        value={field.value}
                        onBlur={field.onBlur}
                        onChange={(event) => {
                          field.onChange(event.target.value);
                          setIsChecked(false);
                        }}
                        label={label}
                        required
                        hasRequiredIndicator
                        aria-invalid={fieldState.invalid}
                        view={fieldState.invalid ? 'negative' : 'default'}
                        leftHelper={fieldState.error?.message}
                      />
                    )}
                  />
                </div>
              );
            })}
            <Button
              type="button"
              view="secondary"
              aria-label={`Удалить получателя ${index + 1}`}
              onClick={() => {
                remove(index);
                setIsChecked(false);
              }}
            >
              Удалить
            </Button>
          </fieldset>
        ))}

        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 12 }}>
          <Button
            type="button"
            view="secondary"
            onClick={() => {
              append({ name: '', account: '' });
              setIsChecked(false);
            }}
          >
            Добавить получателя
          </Button>
          <Button type="submit" view="accent">
            Проверить список
          </Button>
        </div>
        {isChecked && <div role="status">Список проверен.</div>}
      </form>
    </>
  );
}

