import * as React from 'react';
import { Combobox, FiltersActions } from '@daisforge/ui';
import { TableCanvas } from '@daisforge/ui/components/TableCanvas';
import type { ColumnConfig } from '@daisforge/ui/components/TableCanvas';
import { GlobalStyle } from '@daisforge/ui/styles';

type RequestStatus = 'Новая' | 'В работе' | 'Закрыта';

type RequestRow = {
  id: string;
  subject: string;
  requester: string;
  status: RequestStatus;
  submittedOn: string;
};

type RequestFilters = {
  query: string;
  status: string;
};

const defaultFilters: RequestFilters = { query: '', status: '' };

const statusOptions = [
  { value: '', label: 'Все статусы' },
  { value: 'Новая', label: 'Новая' },
  { value: 'В работе', label: 'В работе' },
  { value: 'Закрыта', label: 'Закрыта' },
];

const initialRows: RequestRow[] = [
  { id: 'З-1048', subject: 'Доступ к отчётам', requester: 'Анна Соколова', status: 'Новая', submittedOn: '18.11.2026' },
  { id: 'З-1047', subject: 'Замена рабочего монитора', requester: 'Илья Орлов', status: 'В работе', submittedOn: '18.11.2026' },
  { id: 'З-1046', subject: 'Подключение к тестовой среде', requester: 'Мария Волкова', status: 'Новая', submittedOn: '17.11.2026' },
  { id: 'З-1045', subject: 'Обновление учётной записи', requester: 'Денис Ким', status: 'Закрыта', submittedOn: '16.11.2026' },
  { id: 'З-1044', subject: 'Доступ к базе знаний', requester: 'Ольга Белова', status: 'В работе', submittedOn: '16.11.2026' },
  { id: 'З-1043', subject: 'Установка редактора схем', requester: 'Павел Смирнов', status: 'Закрыта', submittedOn: '13.11.2026' },
];

const columns: readonly ColumnConfig<RequestRow>[] = [
  { key: 'id', name: 'Номер', width: 104 },
  { key: 'subject', name: 'Тема заявки', width: 270 },
  { key: 'requester', name: 'Заявитель', width: 176 },
  { key: 'status', name: 'Статус', width: 120 },
  { key: 'submittedOn', name: 'Дата подачи', width: 132 },
];

export function RequestRegistry() {
  const headingId = React.useId();
  const [requests, setRequests] = React.useState(initialRows);
  const [filters, setFilters] = React.useState(defaultFilters);
  const selectionState = React.useState<ReadonlySet<string | number>>(() => new Set());
  const [selectedIds, setSelectedIds] = selectionState;

  const visibleRows = React.useMemo(() => {
    const query = filters.query.trim().toLocaleLowerCase('ru-RU');

    return requests.filter((request) => {
      const matchesStatus = filters.status === '' || request.status === filters.status;
      const matchesQuery = [request.id, request.subject, request.requester].some(
        (value) => value.toLocaleLowerCase('ru-RU').includes(query),
      );

      return matchesStatus && matchesQuery;
    });
  }, [requests, filters]);

  function updateFilters(update: Partial<RequestFilters>) {
    setFilters((current) => ({ ...current, ...update }));
    setSelectedIds(new Set());
  }

  function updateSelectedStatus(status: RequestStatus) {
    setRequests((current) => current.map((request) => (
      selectedIds.has(request.id) ? { ...request, status } : request
    )));
    setSelectedIds(new Set());
  }

  return (
    <section
      aria-labelledby={headingId}
      style={{ display: 'grid', gap: 16, minWidth: 0, padding: 24 }}
    >
      <GlobalStyle />
      <h1 id={headingId} style={{ margin: 0 }}>Реестр заявок</h1>

      <div role="group" aria-label="Фильтры заявок">
        <FiltersActions
          mainBlock={(
            <div style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: 8 }}>
              <div style={{ flex: '1 1 260px' }}>
                <FiltersActions.TextFieldSearch
                  size="s"
                  aria-label="Поиск по номеру, теме или заявителю"
                  placeholder="Номер, тема или заявитель"
                  autoComplete="off"
                  value={filters.query}
                  onChange={(event) => updateFilters({ query: event.target.value })}
                  onClear={() => updateFilters({ query: '' })}
                />
              </div>
              <div style={{ width: 168 }}>
                <Combobox
                  size="s"
                  aria-label="Статус заявки"
                  placeholder="Все статусы"
                  items={statusOptions}
                  value={filters.status}
                  onChange={(status: string) => updateFilters({ status })}
                />
              </div>
              <FiltersActions.ResetAllFiltersButton
                isVisible={filters.query !== '' || filters.status !== ''}
                onClick={() => updateFilters(defaultFilters)}
              />
            </div>
          )}
        />
      </div>

      <TableCanvas
        columnConfig={columns}
        rows={visibleRows}
        tableConfig={{
          containerStyle: { height: 456, width: '100%' },
          emptyState: {
            enabled: true,
            title: 'Заявки не найдены',
            subtitle: 'Измените запрос или сбросьте фильтры.',
          },
          selecting: {
            showDefault: true,
            state: selectionState,
            rowKeyGetter: (row) => row.id,
          },
          controlBlock: {
            massActionPanel: {
              buttons: [
                {
                  type: 'button',
                  text: 'Взять в работу',
                  view: 'accent',
                  onClick: () => updateSelectedStatus('В работе'),
                },
                {
                  type: 'button',
                  text: 'Закрыть заявки',
                  view: 'secondary',
                  onClick: () => updateSelectedStatus('Закрыта'),
                },
                {
                  type: 'button',
                  text: 'Снять выбор',
                  view: 'secondary',
                  onClick: () => setSelectedIds(new Set()),
                },
              ],
            },
          },
        }}
      />
    </section>
  );
}

import * as React from 'react';
import { Button, Combobox, FiltersActions } from '@daisforge/ui';
import { TableCanvas } from '@daisforge/ui/components/TableCanvas';
import type { ColumnConfig } from '@daisforge/ui/components/TableCanvas';
import { GlobalStyle } from '@daisforge/ui/styles';

type RequestStatus = 'Новая' | 'На рассмотрении' | 'Одобрена' | 'Отклонена';
type RequestRow = {
  id: string;
  subject: string;
  applicant: string;
  receivedAt: string;
  status: RequestStatus;
};

const ALL_STATUSES = 'all';
const REQUEST_STATUSES: RequestStatus[] = ['Новая', 'На рассмотрении', 'Одобрена', 'Отклонена'];
const STATUS_OPTIONS = [
  { value: ALL_STATUSES, label: 'Все статусы' },
  ...REQUEST_STATUSES.map((status) => ({ value: status, label: status })),
];

const INITIAL_REQUESTS: RequestRow[] = [
  { id: 'З-1048', subject: 'Доступ к финансовым отчётам', applicant: 'Анна Волкова', receivedAt: '18.11.2026', status: 'Новая' },
  { id: 'З-1047', subject: 'Замена рабочего ноутбука', applicant: 'Илья Орлов', receivedAt: '18.11.2026', status: 'На рассмотрении' },
  { id: 'З-1046', subject: 'Подключение к проекту «Север»', applicant: 'Мария Ким', receivedAt: '17.11.2026', status: 'Новая' },
  { id: 'З-1045', subject: 'Продление лицензии', applicant: 'Денис Соколов', receivedAt: '17.11.2026', status: 'Одобрена' },
  { id: 'З-1044', subject: 'Доступ к архиву договоров', applicant: 'Ольга Романова', receivedAt: '16.11.2026', status: 'Отклонена' },
  { id: 'З-1043', subject: 'Подключение удалённого доступа', applicant: 'Павел Миронов', receivedAt: '16.11.2026', status: 'На рассмотрении' },
];

const COLUMNS: readonly ColumnConfig<RequestRow>[] = [
  { key: 'id', name: 'Номер', width: 110 },
  { key: 'subject', name: 'Тема заявки', minWidth: 250 },
  { key: 'applicant', name: 'Заявитель', minWidth: 160 },
  { key: 'receivedAt', name: 'Дата подачи', width: 130 },
  { key: 'status', name: 'Статус', width: 170 },
];

function getRequestId(row: RequestRow): string {
  return row.id;
}

export function RequestRegistry() {
  const titleId = React.useId();
  const [requests, setRequests] = React.useState(INITIAL_REQUESTS);
  const [query, setQuery] = React.useState('');
  const [statusFilter, setStatusFilter] = React.useState(ALL_STATUSES);
  const selection = React.useState<ReadonlySet<string | number>>(() => new Set());
  const [selectedIds, setSelectedIds] = selection;

  const visibleRequests = React.useMemo(() => {
    const search = query.trim().toLocaleLowerCase('ru-RU');
    return requests.filter((row) => {
      const matchesStatus = statusFilter === ALL_STATUSES || row.status === statusFilter;
      const matchesSearch = [row.id, row.subject, row.applicant].some((value) =>
        value.toLocaleLowerCase('ru-RU').includes(search),
      );
      return matchesStatus && matchesSearch;
    });
  }, [requests, query, statusFilter]);

  function updateFilters(nextQuery: string, nextStatus: string) {
    if (nextQuery === query && nextStatus === statusFilter) return;
    setQuery(nextQuery);
    setStatusFilter(nextStatus);
    setSelectedIds(new Set());
  }

  function applyStatus(status: RequestStatus) {
    setRequests((current) => current.map((row) =>
      selectedIds.has(row.id) ? { ...row, status } : row,
    ));
    setSelectedIds(new Set());
  }

  return (
    <section aria-labelledby={titleId} style={{ minWidth: 0, padding: 24 }}>
      <GlobalStyle />
      <h1 id={titleId} style={{ margin: '0 0 16px', fontSize: 24 }}>Реестр заявок</h1>
      <div style={{ marginBottom: 12 }}>
        <FiltersActions
          mainBlock={
            <div role="group" aria-label="Фильтры заявок" style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: 8 }}>
              <div style={{ width: 280, maxWidth: '100%' }}>
                <FiltersActions.TextFieldSearch
                  size="s"
                  aria-label="Поиск по номеру, теме или заявителю"
                  placeholder="Номер, тема или заявитель"
                  value={query}
                  onChange={(event: React.ChangeEvent<HTMLInputElement>) => updateFilters(event.currentTarget.value, statusFilter)}
                  onClear={() => updateFilters('', statusFilter)}
                />
              </div>
              <div style={{ width: 180, maxWidth: '100%' }}>
                <Combobox
                  size="s"
                  mode="radio"
                  aria-label="Статус заявки"
                  placeholder="Все статусы"
                  items={STATUS_OPTIONS}
                  value={statusFilter}
                  onChange={(value: string) => updateFilters(query, value)}
                />
              </div>
              <Button
                type="button"
                view="secondary"
                size="s"
                disabled={query === '' && statusFilter === ALL_STATUSES}
                onClick={() => updateFilters('', ALL_STATUSES)}
              >
                Сбросить фильтры
              </Button>
            </div>
          }
        />
      </div>
      <TableCanvas
        rows={visibleRequests}
        columnConfig={COLUMNS}
        tableConfig={{
          containerStyle: { width: '100%', height: 460 },
          selecting: {
            state: selection,
            rowKeyGetter: getRequestId,
            showDefault: true,
          },
          emptyState: {
            enabled: true,
            title: 'Заявки не найдены',
            subtitle: 'Измените условия поиска или сбросьте фильтры.',
            variant: 'not-found',
          },
          controlBlock: {
            massActionPanel: {
              buttons: [
                { type: 'button', text: 'Одобрить', view: 'accent', onClick: () => applyStatus('Одобрена') },
                { type: 'button', text: 'Отклонить', view: 'secondary', onClick: () => applyStatus('Отклонена') },
              ],
            },
          },
        }}
      />
    </section>
  );
}

import * as React from 'react';
import { Button, ModalDFConfirmation } from '@daisforge/ui';
import { GlobalStyle } from '@daisforge/ui/styles';

type Contract = {
  number: string;
};

const initialContract: Contract = { number: 'Д-1042' };

export function DeleteContract() {
  const [contract, setContract] = React.useState<Contract | null>(initialContract);
  const [isConfirmationOpen, setConfirmationOpen] = React.useState(false);

  function closeConfirmation() {
    setConfirmationOpen(false);
  }

  function confirmDeletion() {
    setContract(null);
    closeConfirmation();
  }

  return (
    <>
      <GlobalStyle />
      {contract ? (
        <>
          <p>Договор № {contract.number}</p>
          <Button
            type="button"
            view="negative"
            aria-haspopup="dialog"
            onClick={() => setConfirmationOpen(true)}
          >
            Удалить договор
          </Button>
          <ModalDFConfirmation
            opened={isConfirmationOpen}
            onClose={closeConfirmation}
            hasClose={false}
            content={{
              header: 'Удалить договор?',
              body: `Договор № ${contract.number} будет удалён без возможности восстановления.`,
              secondaryButton: {
                type: 'button',
                text: 'Отмена',
                onClick: closeConfirmation,
              },
              mainButton: {
                type: 'button',
                text: 'Удалить',
                view: 'negative',
                onClick: confirmDeletion,
              },
            }}
          />
        </>
      ) : null}
      <div role="status">{contract === null ? 'Договор удалён.' : ''}</div>
    </>
  );
}

import * as React from 'react';
import { Button, ModalDFConfirmation } from '@daisforge/ui';

type Contract = {
  number: string;
};

const initialContract: Contract = { number: 'Д-001' };

export function DeleteContract(): React.ReactElement {
  const [contract, setContract] = React.useState<Contract | null>(initialContract);
  const [isConfirmationOpen, setConfirmationOpen] = React.useState(false);

  function closeConfirmation(): void {
    setConfirmationOpen(false);
  }

  function confirmDeletion(): void {
    setContract(null);
    closeConfirmation();
  }

  return (
    <>
      {contract && (
        <Button
          type="button"
          view="negative"
          aria-haspopup="dialog"
          onClick={() => setConfirmationOpen(true)}
        >
          Удалить договор
        </Button>
      )}

      <ModalDFConfirmation
        opened={isConfirmationOpen && contract !== null}
        onClose={closeConfirmation}
        hasClose={false}
        content={{
          header: 'Удалить договор?',
          body: contract
            ? `Договор № ${contract.number} будет удалён без возможности восстановления.`
            : 'Договор будет удалён без возможности восстановления.',
          secondaryButton: {
            type: 'button',
            text: 'Отмена',
            onClick: closeConfirmation,
          },
          mainButton: {
            type: 'button',
            text: 'Удалить',
            view: 'negative',
            onClick: confirmDeletion,
          },
        }}
      />

      <div role="status">{contract === null ? 'Договор удалён.' : null}</div>
    </>
  );
}

import * as React from 'react';
import { Button, ModalDF } from '@daisforge/ui';
import { Canvas, TableCanvas } from '@daisforge/ui/components/TableCanvas';
import type { ColumnConfig } from '@daisforge/ui/components/TableCanvas';
import { GlobalStyle } from '@daisforge/ui/styles';

type DealStatus = 'completed' | 'pending' | 'cancelled';

type Deal = {
  id: string;
  date: string;
  counterparty: string;
  status: DealStatus;
  amount: number;
};

const statusDetails: Record<
  DealStatus,
  { label: string; view: 'positive' | 'warning' | 'negative' }
> = {
  completed: { label: 'Завершена', view: 'positive' },
  pending: { label: 'В работе', view: 'warning' },
  cancelled: { label: 'Отменена', view: 'negative' },
};

const mockEntries: ReadonlyArray<Pick<Deal, 'counterparty' | 'status'>> = [
  { counterparty: 'ООО «Север»', status: 'completed' },
  { counterparty: 'АО «Горизонт»', status: 'pending' },
  { counterparty: 'ООО «Вектор»', status: 'completed' },
  { counterparty: 'ООО «Меридиан»', status: 'cancelled' },
  { counterparty: 'АО «Спектр»', status: 'pending' },
];

const dateFormat = new Intl.DateTimeFormat('ru-RU', { timeZone: 'UTC' });
const currencyFormat = new Intl.NumberFormat('ru-RU', {
  style: 'currency',
  currency: 'RUB',
  maximumFractionDigits: 0,
});

const deals = Array.from({ length: 60 }, (_, index): Deal => {
  const entry = mockEntries[index % mockEntries.length] ?? mockEntries[0];
  return {
    id: `СД-${1001 + index}`,
    date: dateFormat.format(new Date(Date.UTC(2026, 6, 1 + index))),
    counterparty: entry?.counterparty ?? 'ООО «Север»',
    status: entry?.status ?? 'completed',
    amount: 45_000 + ((index * 17_350) % 640_000),
  };
});

const totalAmount = deals.reduce((sum, deal) => sum + deal.amount, 0);

const columns: readonly ColumnConfig<Deal>[] = [
  { key: 'id', name: '№ сделки', width: 120 },
  { key: 'date', name: 'Дата', width: 120 },
  { key: 'counterparty', name: 'Контрагент', width: 240 },
  {
    key: 'status',
    name: 'Статус',
    width: 150,
    copyData: (row) => statusDetails[row.status].label,
    renderCell: ({ row, theme }) => {
      const { label, view } = statusDetails[row.status];
      return (
        <Canvas.Container
          alignItems="center"
          padding={{
            left: theme.cellHorizontalPadding,
            right: theme.cellHorizontalPadding,
          }}
        >
          <Canvas.Badge text={label} view={view} pilled />
        </Canvas.Container>
      );
    },
  },
  {
    key: 'amount',
    name: 'Сумма',
    width: 170,
    contentFormat: {
      alignContent: 'right',
      customFormat: (value) => currencyFormat.format(Number(value)),
    },
  },
];

export function DealRegistry(): React.ReactElement {
  const [opened, setOpened] = React.useState(false);
  const closeRegistry = () => setOpened(false);

  return (
    <>
      <GlobalStyle />
      <Button type="button" view="accent" onClick={() => setOpened(true)}>
        Реестр сделок
      </Button>
      <ModalDF
        opened={opened}
        onClose={closeRegistry}
        closeOnEsc
        fullScreen={{ defaultEnabled: true, saveStateAfterClosing: false }}
      >
        <ModalDF.Main
          $css={{
            display: 'grid',
            gridTemplateRows: 'auto minmax(0, 1fr) auto',
            width: '100%',
            height: '100%',
            minWidth: 0,
            minHeight: 0,
            overflow: 'hidden',
          }}
        >
          <ModalDF.Header
            title="Реестр сделок"
            subTitle={`${deals.length} сделок · Демонстрационные данные`}
          />
          <ModalDF.Content
            $css={{
              position: 'relative',
              minWidth: 0,
              minHeight: 0,
              overflow: 'hidden',
            }}
          >
            <div style={{ position: 'absolute', inset: '0 clamp(12px, 2vw, 24px)' }}>
              <TableCanvas
                rows={deals}
                columnConfig={columns}
                tableConfig={{ containerStyle: { width: '100%', height: '100%' } }}
              />
            </div>
          </ModalDF.Content>
          <ModalDF.Footer
            leftBlock={<strong>Итого: {currencyFormat.format(totalAmount)}</strong>}
            rightBlock={
              <Button type="button" view="secondary" onClick={closeRegistry}>
                Закрыть
              </Button>
            }
          />
        </ModalDF.Main>
      </ModalDF>
    </>
