import * as React from 'react';
import { Button, ModalDF, TextS } from '@daisforge/ui';
import { Canvas, TableCanvas } from '@daisforge/ui/components/TableCanvas';
import type { ColumnConfig } from '@daisforge/ui/components/TableCanvas';
import { GlobalStyle } from '@daisforge/ui/styles';

type DealStatus = 'confirmed' | 'pending' | 'cancelled';

type Deal = {
  id: string;
  date: string;
  counterparty: string;
  amount: number;
  status: DealStatus;
};

type StatusBadge = {
  text: string;
  view: 'positive' | 'warning' | 'negative';
};

const statusBadges: Record<DealStatus, StatusBadge> = {
  confirmed: { text: 'Подтверждена', view: 'positive' },
  pending: { text: 'На согласовании', view: 'warning' },
  cancelled: { text: 'Отменена', view: 'negative' },
};

const statuses: readonly DealStatus[] = [
  'confirmed',
  'confirmed',
  'pending',
  'confirmed',
  'cancelled',
];

const counterparties = [
  'ООО «Вектор»',
  'АО «Горизонт»',
  'ООО «Меридиан»',
  'АО «Север»',
  'ООО «Альтаир»',
  'ООО «Спектр»',
];

const dateFormatter = new Intl.DateTimeFormat('ru-RU', {
  day: '2-digit',
  month: '2-digit',
  year: 'numeric',
  timeZone: 'UTC',
});

const currencyFormatter = new Intl.NumberFormat('ru-RU', {
  style: 'currency',
  currency: 'RUB',
  maximumFractionDigits: 0,
});

const deals: Deal[] = Array.from({ length: 60 }, (_, index) => ({
  id: `СД-${String(index + 1).padStart(4, '0')}`,
  date: dateFormatter.format(new Date(Date.UTC(2026, 10, 18 - index))),
  counterparty: counterparties[index % counterparties.length] ?? 'ООО «Вектор»',
  amount: 35_000 + ((index * 17_350) % 480_000),
  status: statuses[index % statuses.length] ?? 'pending',
}));

const totalAmount = deals.reduce((sum, deal) => sum + deal.amount, 0);

const columns: ColumnConfig<Deal>[] = [
  { key: 'id', name: 'Номер сделки', width: 145 },
  { key: 'date', name: 'Дата сделки', width: 140 },
  { key: 'counterparty', name: 'Контрагент', width: 240 },
  {
    key: 'amount',
    name: 'Сумма, ₽',
    width: 160,
    contentFormat: {
      type: 'number',
      locales: ['ru-RU'],
      maximumFractionDigits: 0,
      alignContent: 'right',
    },
  },
  {
    key: 'status',
    name: 'Статус',
    width: 190,
    renderCell: ({ row, theme }) => {
      const badge = statusBadges[row.status];

      return (
        <Canvas.Container
          alignItems="center"
          padding={{
            left: theme.cellHorizontalPadding,
            right: theme.cellHorizontalPadding,
          }}
        >
          <Canvas.Badge text={badge.text} view={badge.view} pilled />
        </Canvas.Container>
      );
    },
  },
];

const tableConfig = {
  containerStyle: { width: '100%', height: '100%' },
  controlBlock: { show: false },
};

const fullScreen = { defaultEnabled: true, saveStateAfterClosing: false };

export function DealsRegistry() {
  const [opened, setOpened] = React.useState(false);

  function closeRegistry() {
    setOpened(false);
