type Payment = {
  id: number;
  date: string;
  amount: number;
  status: 'Оплачен' | 'Запланирован';
};

const contractNumber = 'ДГ-2026-0142';
const payments: Payment[] = [
  { id: 1, date: '15.10.2026', amount: 25000, status: 'Оплачен' },
  { id: 2, date: '15.11.2026', amount: 25000, status: 'Оплачен' },
  { id: 3, date: '15.12.2026', amount: 25000, status: 'Запланирован' },
];

const columns: readonly ColumnConfig<Payment>[] = [
  { key: 'date', name: 'Дата платежа', minWidth: 110 },
  {
    key: 'amount',
    name: 'Сумма, ₽',
    minWidth: 95,
    contentFormat: {
      type: 'number',
      locales: ['ru-RU'],
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
      alignContent: 'right',
    },
  },
  { key: 'status', name: 'Статус', minWidth: 120 },
];

function downloadPayments() {
  const records = [
    ['Номер договора', 'Дата платежа', 'Сумма (₽)', 'Статус'],
    ...payments.map(({ date, amount, status }) => [
      contractNumber,
      date,
      amount.toFixed(2).replace('.', ','),
      status,
    ]),
  ];
  const csv = records
    .map((record) => record.map((field) => `"${field.replace(/"/g, '""')}"`).join(';'))
    .join('\r\n');
  const url = URL.createObjectURL(new Blob(['\uFEFF', csv], { type: 'text/csv;charset=utf-8' }));
  const link = document.createElement('a');
  link.href = url;
  link.download = `Платежи-${contractNumber}.csv`;
  document.body.appendChild(link);
  link.click();
  link.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 1000);
}

