import * as React from 'react';
import { Button, IconButton } from '@daisforge/ui';
import { IconSettingsOutline } from '@daisforge/ui/icons';
import { GlobalStyle } from '@daisforge/ui/styles';

type ListItem = {
  id: number;
  name: string;
};

const initialItems: readonly ListItem[] = [
  { id: 1, name: 'Элемент 1' },
  { id: 2, name: 'Элемент 2' },
];

export function ListActions() {
  const sourceItems = React.useRef(initialItems);
  const [items, setItems] = React.useState(initialItems);
  const [settingsOpen, setSettingsOpen] = React.useState(false);
  const [newestFirst, setNewestFirst] = React.useState(false);
  const [status, setStatus] = React.useState('');
  const settingsId = React.useId();

  function createItem() {
    const id = sourceItems.current.length + 1;
    const item = { id, name: `Элемент ${id}` };
    sourceItems.current = [...sourceItems.current, item];
    setItems(sourceItems.current);
    setStatus(`Создан элемент №${id}`);
  }

  function refreshList() {
    setItems([...sourceItems.current]);
    setStatus('Список обновлён');
  }

  const visibleItems = newestFirst ? [...items].reverse() : items;

  return (
    <>
      <GlobalStyle />
      <section aria-label="Список элементов">
        <div
          role="group"
          aria-label="Действия над списком"
          style={{ display: 'flex', flexWrap: 'nowrap', alignItems: 'center', gap: 8 }}
        >
          <Button type="button" size="s" view="accent" onClick={createItem}>
            Создать
          </Button>
          <Button type="button" size="s" view="secondary" onClick={refreshList}>
            Обновить
          </Button>
          <IconButton
            type="button"
            size="s"
            view="secondary"
            aria-label="Настройки"
            title="Настройки"
            aria-expanded={settingsOpen}
            aria-controls={settingsId}
            onClick={() => setSettingsOpen((open) => !open)}
          >
            <IconSettingsOutline color="inherit" />
          </IconButton>
        </div>

        <div id={settingsId} hidden={!settingsOpen} style={{ marginTop: 8 }}>
          <label>
            <input
              type="checkbox"
              checked={newestFirst}
              onChange={(event) => setNewestFirst(event.currentTarget.checked)}
            />{' '}
            Сначала новые
          </label>
        </div>

        <ul>
          {visibleItems.map((item) => <li key={item.id}>{item.name}</li>)}
        </ul>
        <div role="status">{status}</div>
      </section>
    </>
  );
}

import * as React from 'react';
import { Button, IconButton, Switch } from '@daisforge/ui';
import { GlobalStyle } from '@daisforge/ui/styles';

interface ListItem {
  id: number;
  name: string;
}

const initialItems: readonly ListItem[] = [
  { id: 1, name: 'Запись 1' },
  { id: 2, name: 'Запись 2' },
];

const actionsStyle: React.CSSProperties = {
  display: 'flex',
  flexWrap: 'nowrap',
  alignItems: 'center',
  gap: 8,
};

export function ListActions(): React.ReactElement {
  const sourceItems = React.useRef(initialItems);
  const [items, setItems] = React.useState(initialItems);
  const [settingsOpen, setSettingsOpen] = React.useState(false);
  const [newestFirst, setNewestFirst] = React.useState(false);
  const [lastRefresh, setLastRefresh] = React.useState<Date | null>(null);
  const settingsId = React.useId();

  function createItem() {
    const currentItems = sourceItems.current;
    const id = (currentItems[currentItems.length - 1]?.id ?? 0) + 1;
    const updatedItems = [...currentItems, { id, name: `Запись ${id}` }];
    sourceItems.current = updatedItems;
    setItems(updatedItems);
  }

  function refreshList() {
    setItems([...sourceItems.current]);
    setLastRefresh(new Date());
  }

  const visibleItems = newestFirst ? [...items].reverse() : items;

  return (
    <>
      <GlobalStyle />
      <section aria-label="Список записей">
        <div role="group" aria-label="Действия со списком" style={actionsStyle}>
          <Button type="button" view="accent" size="s" onClick={createItem}>
            Создать
          </Button>
          <Button type="button" view="secondary" size="s" onClick={refreshList}>
            Обновить
          </Button>
          <IconButton
            type="button"
            view="secondary"
            size="s"
            aria-label="Настройки"
            title="Настройки"
            aria-expanded={settingsOpen}
            aria-controls={settingsId}
            onClick={() => setSettingsOpen((open) => !open)}
          >
            <span aria-hidden="true">⚙︎</span>
          </IconButton>
        </div>

        <div id={settingsId} hidden={!settingsOpen} style={{ marginTop: 8 }}>
          <Switch
            label="Сначала новые записи"
            checked={newestFirst}
            onChange={() => setNewestFirst((current) => !current)}
          />
        </div>

        <ul>
          {visibleItems.map((item) => (
            <li key={item.id}>{item.name}</li>
          ))}
        </ul>

        <div role="status">
          {lastRefresh && `Список обновлён в ${lastRefresh.toLocaleTimeString('ru-RU')}`}
        </div>
      </section>
    </>
  );
}

