const cities = [
  'Москва',
  'Санкт-Петербург',
  'Новосибирск',
  'Екатеринбург',
  'Казань',
  'Нижний Новгород',
  'Красноярск',
  'Челябинск',
  'Самара',
  'Ростов-на-Дону',
];

const citySuggestions = cities.map((city) => ({ label: city, value: city }));

type CityFieldState = {
  inputValue: string;
  selectedCity: string | null;
};

const emptyField: CityFieldState = { inputValue: '', selectedCity: null };

export function CityAutocomplete() {
  const [field, setField] = React.useState<CityFieldState>(emptyField);
  const query = field.inputValue.trim().toLocaleLowerCase('ru');
  const suggestions = query && field.selectedCity === null
    ? citySuggestions.filter(({ label }) => label.toLocaleLowerCase('ru').includes(query))
    : [];

  return (
    <>
      <GlobalStyle />
      <Autocomplete
        label="Город"
        placeholder="Начните вводить название города"
        autoComplete="off"
        threshold={1}
        value={field.inputValue}
        suggestions={suggestions}
        filter={() => true}
        onChange={(event) => {
          const inputValue = event.currentTarget.value;
          setField((previous) => ({
            inputValue,
            selectedCity: previous.selectedCity === inputValue ? previous.selectedCity : null,
          }));
        }}
        onSuggestionSelect={({ label }) => {
          setField({ inputValue: label, selectedCity: label });
        }}
        onClear={() => setField(emptyField)}
      />
    </>
  );
}

