import * as React from 'react';
import { DatePickerRange } from '@daisforge/ui';

type ReportPeriod = [Date | '', Date | ''];

function parseDate(value: unknown): Date | '' | undefined {
  if (value === '' || value === null || value === undefined) {
    return '';
  }

  if (value instanceof Date) {
    return Number.isNaN(value.getTime()) ? undefined : value;
  }

  const match = typeof value === 'string'
    ? /^(\d{2})\.(\d{2})\.(\d{4})$/.exec(value)
    : null;

  if (!match) {
    return undefined;
  }

  const day = Number(match[1]);
  const month = Number(match[2]);
  const year = Number(match[3]);
  const date = new Date(0);
  date.setFullYear(year, month - 1, day);
  date.setHours(0, 0, 0, 0);

  if (date.getFullYear() === year && date.getMonth() === month - 1 && date.getDate() === day) {
    return date;
  }

  return undefined;
}

export function ReportPeriodPicker() {
  const [period, setPeriod] = React.useState<ReportPeriod>(['', '']);
  const today = new Date();
  today.setHours(23, 59, 59, 999);

  function commitDate(index: 0 | 1, value: unknown) {
    const date = parseDate(value);
    if (date === undefined || (date !== '' && date.getTime() > today.getTime())) {
      return;
    }

    setPeriod(([start, end]) => (index === 0 ? [date, end] : [start, date]));
  }

  return (
    <DatePickerRange
      label="Период"
      lang="ru"
      format="DD.MM.YYYY"
      max={today}
      includeEdgeDates
      preserveInvalidOnBlur={false}
      value={period}
      onCommitFirstDate={(value) => commitDate(0, value)}
      onCommitSecondDate={(value) => commitDate(1, value)}
    />
  );
}

import * as React from 'react';
import { DatePickerRange } from '@daisforge/ui';

type ReportPeriod = [string, string];

function toPeriodDate(value: unknown, maxDate: Date): string | undefined {
  if (value === '' || value === null || value === undefined) {
    return '';
  }

  if (value instanceof Date) {
    if (!Number.isFinite(value.getTime()) || value > maxDate) {
      return undefined;
    }

    const day = String(value.getDate()).padStart(2, '0');
    const month = String(value.getMonth() + 1).padStart(2, '0');
    const year = String(value.getFullYear()).padStart(4, '0');
    return `${day}.${month}.${year}`;
  }

  if (typeof value !== 'string' || !/^\d{2}\.\d{2}\.\d{4}$/.test(value)) {
    return undefined;
  }

  const day = Number(value.slice(0, 2));
  const month = Number(value.slice(3, 5));
  const year = Number(value.slice(6));
  const date = new Date(0);
  date.setFullYear(year, month - 1, day);
  date.setHours(0, 0, 0, 0);

  if (
    date.getFullYear() !== year ||
    date.getMonth() !== month - 1 ||
    date.getDate() !== day ||
    date > maxDate
  ) {
    return undefined;
  }

  return value;
}

export function ReportPeriodPicker() {
  const [period, setPeriod] = React.useState<ReportPeriod>(['', '']);
  const today = new Date();
  today.setHours(23, 59, 59, 999);

  function commitDate(index: 0 | 1, value: unknown) {
    const date = toPeriodDate(value, today);
    if (date === undefined) {
      return;
    }

    setPeriod((previousPeriod) => {
      const nextPeriod: ReportPeriod = [...previousPeriod];
      nextPeriod[index] = date;
      return nextPeriod;
    });
  }

  return (
    <DatePickerRange
      label="Период"
      format="DD.MM.YYYY"
      lang="ru"
      max={today}
      includeEdgeDates
      value={period}
      onCommitFirstDate={(value) => commitDate(0, value)}
      onCommitSecondDate={(value) => commitDate(1, value)}
    />
  );
}

import * as React from 'react';
import { Attach } from '@daisforge/ui';

const MAX_FILE_SIZE_BYTES = 5 * 1024 * 1024;

export function RequestAttachment() {
  const [selectedFile, setSelectedFile] = React.useState<File | null>(null);
  const isTooLarge = selectedFile !== null && selectedFile.size > MAX_FILE_SIZE_BYTES;

  function handleFileChange(event: React.FormEvent<HTMLElement>) {
    const input = event.target;
    if (!(input instanceof HTMLInputElement) || input.type !== 'file') {
      return;
    }

    const file = input.files?.item(0);
    if (!file) {
      return;
    }

    setSelectedFile(file);
    input.value = '';
  }

  return (
    <Attach
      text="Прикрепить файл к заявке"
      type="button"
      files={selectedFile ? [selectedFile] : []}
      hasAttachment={selectedFile !== null}
      hideButtonOnAttach={false}
      onChange={handleFileChange}
      onClear={() => setSelectedFile(null)}
      helperText={isTooLarge ? 'Размер файла превышает 5 МБ.' : undefined}
      helperTextView={isTooLarge ? 'negative' : 'default'}
    />
  );
}

