            count={pageCount}
            value={page}
            perPage={PAGE_SIZE}
            hasPageRange
            hasPerPage={false}
            onChange={(nextPage) => {
              if (nextPage !== undefined && nextPage >= 1 && nextPage <= pageCount) {
                setPage(nextPage);
              }
            }}
          />
        </nav>
      </section>
    </>
  );
}

