import * as React from 'react';
import { FormProvider, useForm } from 'react-hook-form';
import { Button, FormDatePicker, FormSelect, FormTextField } from '@daisforge/ui';
import { GlobalStyle } from '@daisforge/ui/styles';

type Profile = {
  fullName: string;
  email: string;
  birthDate: string;
  city: string;
};

const cityOptions = [
  { value: 'moscow', label: 'Москва' },
  { value: 'saint-petersburg', label: 'Санкт-Петербург' },
  { value: 'kazan', label: 'Казань' },
  { value: 'yekaterinburg', label: 'Екатеринбург' },
  { value: 'novosibirsk', label: 'Новосибирск' },
];

const emailPattern = /^[^\s@]+@[^\s@.]+(?:\.[^\s@.]+)+$/;

export function UserProfileForm() {
  const headingId = React.useId();
  const [savedProfile, setSavedProfile] = React.useState<Profile | null>(null);
  const form = useForm<Profile>({
    defaultValues: { fullName: '', email: '', birthDate: '', city: '' },
    mode: 'onSubmit',
    reValidateMode: 'onChange',
  });
  const { handleSubmit, reset, formState: { isDirty } } = form;

  function saveProfile(values: Profile) {
    const profile = {
      ...values,
      fullName: values.fullName.trim(),
      email: values.email.trim(),
    };
    setSavedProfile(profile);
    reset(profile);
  }

  return (
    <>
      <GlobalStyle />
      <FormProvider {...form}>
        <form
          aria-labelledby={headingId}
          noValidate
          onSubmit={handleSubmit(saveProfile)}
