            name="fullName"
            label="ФИО"
            labelPlacement="outer"
            autoComplete="name"
            hasRequiredIndicator
            options={{
              required: 'Введите ФИО',
              pattern: { value: /\S/, message: 'Введите ФИО' },
            }}
          />
          <FormTextField
            name="email"
            label="E-mail"
            labelPlacement="outer"
            type="email"
            autoComplete="email"
            hasRequiredIndicator
            options={{
              required: 'Введите e-mail',
              validate: (value: string) => {
                const email = value.trim();
                if (!email) return 'Введите e-mail';
                return emailPattern.test(email) || 'Введите e-mail в формате name@example.com';
              },
            }}
          />
          <FormDatePicker
            name="birthDate"
            label="Дата рождения"
            labelPlacement="outer"
            placeholder="ДД.ММ.ГГГГ"
            lang="ru"
            hasRequiredIndicator
            closeAfterDateSelect
