import * as React from 'react';
import { Button, FormDatePicker, FormSelect, FormTextField } from '@daisforge/ui';
import { GlobalStyle } from '@daisforge/ui/styles';
import { FormProvider, useForm } from 'react-hook-form';
import { z } from 'zod';

type ProfileValues = {
  fullName: string;
  email: string;
  birthDate: unknown;
  city: string;
};

const cities = [
  { value: 'moscow', label: 'Москва' },
  { value: 'saint-petersburg', label: 'Санкт-Петербург' },
  { value: 'kazan', label: 'Казань' },
  { value: 'yekaterinburg', label: 'Екатеринбург' },
  { value: 'novosibirsk', label: 'Новосибирск' },
];

const emailFormat = z.string().trim().email();

export function ProfileForm() {
  const form = useForm<ProfileValues>({
    defaultValues: { fullName: '', email: '', birthDate: '', city: '' },
  });
  const { errors, isSubmitSuccessful } = form.formState;
  const [savedProfile, setSavedProfile] = React.useState<ProfileValues | null>(null);

  function saveProfile(values: ProfileValues) {
    setSavedProfile({
      ...values,
      fullName: values.fullName.trim(),
      email: values.email.trim(),
    });
  }

  return (
    <FormProvider {...form}>
      <GlobalStyle />
      <form
        aria-label="Профиль пользователя"
        noValidate
        onSubmit={form.handleSubmit(saveProfile)}
        style={{ display: 'grid', gap: '16px', maxWidth: '420px' }}
      >
        <FormTextField
          name="fullName"
          label="ФИО"
          labelPlacement="outer"
          autoComplete="name"
          hasRequiredIndicator
          leftHelper={errors.fullName?.message}
          options={{
            required: 'Введите ФИО',
            validate: (value: unknown) =>
              (typeof value === 'string' && value.trim().length > 0) || 'Введите ФИО',
          }}
        />
        <FormTextField
          name="email"
          label="E-mail"
          labelPlacement="outer"
          autoComplete="email"
          hasRequiredIndicator
          leftHelper={errors.email?.message}
          options={{
            required: 'Введите e-mail',
            validate: (value: unknown) => {
              if (typeof value !== 'string' || value.trim().length === 0) {
                return 'Введите e-mail';
              }
              return emailFormat.safeParse(value).success || 'Введите e-mail в корректном формате';
            },
          }}
        />
        <FormDatePicker
          name="birthDate"
          label="Дата рождения"
          labelPlacement="outer"
          lang="ru"
          placeholder="ДД.ММ.ГГГГ"
          hasRequiredIndicator
          preserveInvalidOnBlur
          invalidFormatMessage="Введите корректную дату рождения"
          leftHelper={errors.birthDate?.message}
          options={{ required: 'Укажите дату рождения' }}
        />
        <FormSelect
          name="city"
          label="Город"
          labelPlacement="outer"
          placeholder="Выберите город"
          items={cities}
          type="button"
          hasRequiredIndicator
          helperText={errors.city?.message}
          options={{ required: 'Выберите город' }}
        />
        <div>
          <Button type="submit" view="accent">Сохранить</Button>
          <div role="status">{savedProfile && isSubmitSuccessful ? 'Профиль сохранён.' : ''}</div>
        </div>
      </form>
    </FormProvider>
  );
}

import * as React from 'react';
import { Button, FormCheckbox, FormTextField } from '@daisforge/ui';
import { GlobalStyle } from '@daisforge/ui/styles';
import { zodResolver } from '@hookform/resolvers/zod';
import { FormProvider, useForm } from 'react-hook-form';
import { z } from 'zod';

const amountError = 'Введите сумму больше нуля.';

const paymentSchema = z.object({
  amount: z.string()
    .trim()
    .transform((value) => value.replace(',', '.'))
    .refine((value) => {
      const amount = Number(value);
      return /^\+?(?:\d+(?:\.\d*)?|\.\d+)$/.test(value)
        && Number.isFinite(amount)
        && amount > 0;
    }, amountError),
  purpose: z.string().trim().min(1, 'Укажите назначение платежа.'),
  acceptedTerms: z.boolean().refine(
    (accepted): boolean => accepted,
    'Подтвердите согласие с условиями.',
  ),
});

type PaymentFields = z.infer<typeof paymentSchema>;

type SubmittedPayment = {
  amount: number;
  purpose: string;
};

const defaultValues: PaymentFields = {
  amount: '',
  purpose: '',
  acceptedTerms: false,
};

export function PaymentForm() {
  const [submittedPayment, setSubmittedPayment] = React.useState<SubmittedPayment | null>(null);
  const termsErrorId = React.useId();
  const form = useForm<PaymentFields>({
    defaultValues,
    resolver: zodResolver(paymentSchema),
  });
  const { errors, isSubmitting } = form.formState;
  const acceptedTerms = form.watch('acceptedTerms');
  const termsError = errors.acceptedTerms?.message;

  const submitPayment = form.handleSubmit(({ amount, purpose }) => {
    setSubmittedPayment({ amount: Number(amount), purpose });
    form.reset();
  });

  return (
    <FormProvider {...form}>
      <GlobalStyle />
      <form
        aria-label="Форма платежа"
        noValidate
        onSubmit={submitPayment}
        style={{ display: 'grid', gap: '1rem', maxWidth: '28rem' }}
      >
        <FormTextField<PaymentFields>
          name="amount"
          label="Сумма"
          inputMode="decimal"
          hasRequiredIndicator
        />
        <FormTextField<PaymentFields>
          name="purpose"
          label="Назначение платежа"
          hasRequiredIndicator
        />
        <div>
          <FormCheckbox<PaymentFields>
            name="acceptedTerms"
            label="Я согласен с условиями"
            aria-invalid={Boolean(termsError)}
            aria-describedby={termsError ? termsErrorId : undefined}
          />
          {termsError && <div id={termsErrorId} role="alert">{termsError}</div>}
        </div>
        <div>
          <Button type="submit" view="accent" disabled={!acceptedTerms || isSubmitting}>
            Оплатить
          </Button>
        </div>
        <div role="status">
          {submittedPayment && (
            <>Данные платежа приняты. Сумма: {submittedPayment.amount.toLocaleString('ru-RU', { maximumSignificantDigits: 21 })}. Назначение: {submittedPayment.purpose}.</>
          )}
        </div>
      </form>
    </FormProvider>
  );
}

import * as React from 'react';
import { zodResolver } from '@hookform/resolvers/zod';
import { FormProvider, useForm, useWatch } from 'react-hook-form';
import { z } from 'zod';
import { Button, FormCheckbox, FormTextField } from '@daisforge/ui';
import { GlobalStyle } from '@daisforge/ui/styles';

const decimalPattern = /^[+-]?(?:\d+(?:[.,]\d*)?|[.,]\d+)(?:[eE][+-]?\d+)?$/;

function parseAmount(value: string): number {
  return decimalPattern.test(value) ? Number(value.replace(',', '.')) : NaN;
}

const paymentSchema = z.object({
  amount: z.string().trim().refine((value) => {
    const amount = parseAmount(value);
    return Number.isFinite(amount) && amount > 0;
  }, 'Введите сумму больше нуля'),
  purpose: z.string().trim().min(1, 'Укажите назначение платежа'),
  acceptedTerms: z.boolean().refine((value) => value, 'Подтвердите согласие с условиями'),
});

type PaymentFormValues = z.infer<typeof paymentSchema>;

type SubmittedPayment = {
  amount: number;
  purpose: string;
};

const defaultValues: PaymentFormValues = {
  amount: '',
  purpose: '',
  acceptedTerms: false,
};

export function PaymentForm() {
  const [submittedPayment, setSubmittedPayment] = React.useState<SubmittedPayment | null>(null);
  const form = useForm<PaymentFormValues>({
    defaultValues,
    resolver: zodResolver(paymentSchema),
  });
  const { control, formState: { errors, isSubmitting }, handleSubmit, reset } = form;
  const acceptedTerms = useWatch({ control, name: 'acceptedTerms' });
  const headingId = React.useId();

  function submitPayment(values: PaymentFormValues) {
    setSubmittedPayment({
      amount: parseAmount(values.amount),
      purpose: values.purpose,
    });
    reset();
  }

  return (
    <FormProvider {...form}>
      <GlobalStyle />
      <form
        aria-labelledby={headingId}
        noValidate
        onSubmit={handleSubmit(submitPayment)}
        style={{ display: 'grid', gap: 16, maxWidth: 480 }}
      >
        <h2 id={headingId} style={{ margin: 0 }}>Платёж</h2>
        <FormTextField<PaymentFormValues> name="amount" label="Сумма" />
        <FormTextField<PaymentFormValues> name="purpose" label="Назначение платежа" />
        <div>
          <FormCheckbox<PaymentFormValues>
            name="acceptedTerms"
            label="Я согласен с условиями оплаты"
          />
          {errors.acceptedTerms?.message && (
            <div role="alert">{errors.acceptedTerms.message}</div>
          )}
        </div>
        <div>
          <Button type="submit" view="accent" disabled={acceptedTerms !== true || isSubmitting}>
            Оплатить
          </Button>
        </div>
        <div role="status">
          {submittedPayment && (
            <span>
              Данные платежа сохранены. Сумма — {submittedPayment.amount}. Назначение — {submittedPayment.purpose}.
            </span>
          )}
        </div>
      </form>
    </FormProvider>
  );
}

import * as React from 'react';
import { Button, FormTextField } from '@daisforge/ui';
import { GlobalStyle } from '@daisforge/ui/styles';
import { FormProvider, useFieldArray, useForm } from 'react-hook-form';

interface Recipient {
  name: string;
  account: string;
}

interface RecipientsFormValues {
  recipients: Recipient[];
}

function createRecipient(): Recipient {
  return { name: '', account: '' };
}

function requiredText(message: string) {
  return {
    required: message,
    validate: (value: unknown) =>
      (typeof value === 'string' && value.trim().length > 0) || message,
  };
}

const nameOptions = requiredText('Введите имя получателя');
const accountOptions = requiredText('Введите счёт получателя');

export function RecipientsForm() {
  const headingId = React.useId();
  const [validated, setValidated] = React.useState(false);
  const form = useForm<RecipientsFormValues>({
    defaultValues: { recipients: [createRecipient()] },
  });
  const { fields, append, remove } = useFieldArray({
    control: form.control,
    name: 'recipients',
  });

  return (
    <FormProvider {...form}>
      <GlobalStyle />
      <form
        aria-labelledby={headingId}
        noValidate
        onChange={() => setValidated(false)}
        onSubmit={form.handleSubmit(
          () => setValidated(true),
          () => setValidated(false),
        )}
        style={{ display: 'grid', gap: '1rem', maxWidth: '48rem' }}
      >
        <h1 id={headingId}>Получатели</h1>

        {fields.map((recipient, index) => (
          <fieldset
            key={recipient.id}
            style={{
              display: 'flex',
              flexWrap: 'wrap',
              alignItems: 'flex-start',
              gap: '0.75rem',
              minWidth: 0,
            }}
          >
            <legend>Получатель {index + 1}</legend>
            <div style={{ flex: '1 1 12rem', minWidth: 0 }}>
              <FormTextField<RecipientsFormValues>
                name={`recipients.${index}.name`}
                label="Имя"
                options={nameOptions}
                hasRequiredIndicator
              />
            </div>
            <div style={{ flex: '1 1 12rem', minWidth: 0 }}>
              <FormTextField<RecipientsFormValues>
                name={`recipients.${index}.account`}
                label="Счёт"
                options={accountOptions}
                hasRequiredIndicator
              />
            </div>
            <Button
              type="button"
              text="Удалить"
              aria-label={`Удалить получателя ${index + 1}`}
              view="secondary"
              onClick={() => {
                remove(index);
                setValidated(false);
              }}
            />
          </fieldset>
        ))}

        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.75rem' }}>
          <Button
            type="button"
            text="Добавить получателя"
            view="secondary"
            onClick={() => {
              append(createRecipient());
              setValidated(false);
            }}
          />
          <Button type="submit" text="Проверить" view="accent" />
        </div>

        {validated && <p role="status">Форма прошла проверку.</p>}
      </form>
    </FormProvider>
  );
}

import * as React from 'react';
import { Controller, useFieldArray, useForm } from 'react-hook-form';
import type { Control } from 'react-hook-form';
import { Button, TextField } from '@daisforge/ui';
import { GlobalStyle } from '@daisforge/ui/styles';

type Recipient = {
  name: string;
  account: string;
};

type FormValues = {
  recipients: Recipient[];
};

type RecipientFieldProps = {
  control: Control<FormValues>;
  name: `recipients.${number}.${keyof Recipient}`;
  label: string;
  requiredMessage: string;
};

function RecipientField({ control, name, label, requiredMessage }: RecipientFieldProps) {
  const inputId = React.useId();
  const errorId = `${inputId}-error`;

  return (
    <div style={{ flex: '1 1 13rem', minWidth: 0 }}>
      <Controller
        control={control}
        name={name}
        rules={{ validate: (value) => value.trim().length > 0 || requiredMessage }}
        render={({ field, fieldState: { error } }) => (
          <TextField
            id={inputId}
            label={label}
            labelPlacement="outer"
            hasRequiredIndicator
            name={field.name}
            value={field.value}
            onChange={(event) => field.onChange(event.target.value)}
            onBlur={field.onBlur}
            aria-required="true"
            aria-invalid={Boolean(error)}
            aria-describedby={error ? errorId : undefined}
            view={error ? 'negative' : 'default'}
            leftHelper={error && <span id={errorId} role="alert">{error.message}</span>}
          />
        )}
      />
    </div>
  );
}

