import * as React from 'react';
import { Button, FiltersActions, Select, TextFieldSearch } from '@daisforge/ui';
import { TableCanvas } from '@daisforge/ui/components/TableCanvas';
import type { ColumnConfig } from '@daisforge/ui/components/TableCanvas';
import { GlobalStyle } from '@daisforge/ui/styles';

type RequestStatus = 'Новая' | 'В работе' | 'Закрыта';

type RequestRow = {
  id: string;
  subject: string;
  requester: string;
  status: RequestStatus;
};

const initialRows: RequestRow[] = [
  { id: 'З-1042', subject: 'Доступ к проекту', requester: 'Анна Орлова', status: 'Новая' },
  { id: 'З-1041', subject: 'Обновление контактных данных', requester: 'Илья Котов', status: 'В работе' },
  { id: 'З-1040', subject: 'Восстановление учётной записи', requester: 'Мария Волкова', status: 'Новая' },
  { id: 'З-1039', subject: 'Выгрузка отчёта за октябрь', requester: 'Олег Соколов', status: 'Закрыта' },
  { id: 'З-1038', subject: 'Настройка уведомлений', requester: 'Дарья Морозова', status: 'В работе' },
  { id: 'З-1037', subject: 'Замена рабочего ноутбука', requester: 'Алексей Попов', status: 'Новая' },
];

const columns: readonly ColumnConfig<RequestRow>[] = [
  { key: 'id', name: 'Номер', width: 112 },
  { key: 'subject', name: 'Тема заявки', minWidth: 250 },
  { key: 'requester', name: 'Заявитель', width: 190 },
  { key: 'status', name: 'Статус', width: 140 },
];

const allStatuses = 'all';
const statusOptions = [
  { value: allStatuses, label: 'Все статусы' },
  { value: 'Новая', label: 'Новая' },
  { value: 'В работе', label: 'В работе' },
  { value: 'Закрыта', label: 'Закрыта' },
];

const getRowKey = (row: RequestRow) => row.id;

export function RequestsRegistry() {
  const headingId = React.useId();
  const [rows, setRows] = React.useState(initialRows);
  const [search, setSearch] = React.useState('');
  const [status, setStatus] = React.useState(allStatuses);
  const [notice, setNotice] = React.useState('');
  const selection = React.useState<ReadonlySet<string | number>>(() => new Set());
  const [selectedIds, setSelectedIds] = selection;

  const visibleRows = React.useMemo(() => {
    const query = search.trim().toLocaleLowerCase('ru');

    return rows.filter((row) => {
      const matchesStatus = status === allStatuses || row.status === status;
      const matchesSearch = [row.id, row.subject, row.requester].some((value) =>
        value.toLocaleLowerCase('ru').includes(query),
      );

      return matchesStatus && matchesSearch;
    });
  }, [rows, search, status]);

  const selectedRows = visibleRows.filter((row) => selectedIds.has(row.id));

  function updateFilters(nextSearch: string, nextStatus: string) {
    if (nextSearch === search && nextStatus === status) return;

    setSearch(nextSearch);
    setStatus(nextStatus);
    setSelectedIds(new Set());
    setNotice('');
  }

  function applyBulkStatus(nextStatus: 'В работе' | 'Закрыта') {
    const idsToUpdate = new Set(
      selectedRows
        .filter((row) => nextStatus === 'В работе' ? row.status === 'Новая' : row.status !== 'Закрыта')
        .map(getRowKey),
    );
    if (idsToUpdate.size === 0) return;

    setRows((currentRows) => currentRows.map((row) =>
      idsToUpdate.has(row.id) ? { ...row, status: nextStatus } : row,
    ));
    setSelectedIds(new Set());
    setNotice(nextStatus === 'В работе'
      ? `Взято в работу заявок: ${idsToUpdate.size}`
      : `Закрыто заявок: ${idsToUpdate.size}`);
  }

  return (
    <section aria-labelledby={headingId} style={{ width: '100%', padding: 24, boxSizing: 'border-box' }}>
      <GlobalStyle />
      <h1 id={headingId} style={{ margin: '0 0 20px' }}>Реестр заявок</h1>

      <FiltersActions
        mainBlock={(
          <div role="group" aria-label="Фильтры заявок" style={{ display: 'flex', flexWrap: 'wrap', gap: 12, alignItems: 'center' }}>
            <div style={{ width: 320, maxWidth: '100%' }}>
              <TextFieldSearch
                aria-label="Поиск по номеру, теме или заявителю"
                placeholder="Номер, тема или заявитель"
                value={search}
                onChange={(event) => updateFilters(event.target.value, status)}
                onClear={() => updateFilters('', status)}
              />
            </div>
            <div style={{ width: 180, maxWidth: '100%' }}>
              <Select
                label="Статус"
                mode="radio"
                items={statusOptions}
                value={status}
                onChange={(value: unknown) => {
                  if (typeof value === 'string') updateFilters(search, value);
                }}
              />
            </div>
            <Button
              type="button"
              size="s"
              view="secondary"
              disabled={search === '' && status === allStatuses}
              onClick={() => updateFilters('', allStatuses)}
            >
              Сбросить фильтры
            </Button>
          </div>
        )}
      />

      <div style={{ marginTop: 12 }}>
        <TableCanvas
          rows={visibleRows}
          columnConfig={columns}
          tableConfig={{
            containerStyle: { width: '100%', height: 440 },
            selecting: {
              state: selection,
              rowKeyGetter: getRowKey,
              showDefault: true,
            },
            controlBlock: {
              massActionPanel: {
                buttons: [
                  {
                    type: 'button',
                    text: 'Взять в работу',
                    view: 'accent',
                    disabled: !selectedRows.some((row) => row.status === 'Новая'),
                    onClick: () => applyBulkStatus('В работе'),
                  },
                  {
                    type: 'button',
                    text: 'Закрыть заявки',
                    view: 'secondary',
                    disabled: !selectedRows.some((row) => row.status !== 'Закрыта'),
                    onClick: () => applyBulkStatus('Закрыта'),
                  },
                  {
                    type: 'button',
                    text: 'Снять выбор',
                    view: 'secondary',
                    onClick: () => setSelectedIds(new Set()),
                  },
                ],
              },
            },
            emptyState: {
              enabled: visibleRows.length === 0,
              size: 's',
              title: 'Заявки не найдены',
              subtitle: 'Измените условия поиска или сбросьте фильтры.',
              variant: 'not-found',
            },
          }}
        />
      </div>
      <div role="status">{notice}</div>
    </section>
  );
}

