type DealStatus = 'completed' | 'pending' | 'cancelled';

type Deal = {
  id: string;
  date: string;
  counterparty: string;
  amount: number;
  status: DealStatus;
};

const STATUS: Record<DealStatus, { label: string; view: 'positive' | 'warning' | 'negative' }> = {
  completed: { label: 'Завершена', view: 'positive' },
  pending: { label: 'В работе', view: 'warning' },
  cancelled: { label: 'Отменена', view: 'negative' },
};

const MOCK_DEALS: Pick<Deal, 'counterparty' | 'amount' | 'status'>[] = [
  { counterparty: 'ООО «Север Логистика»', amount: 248_000, status: 'completed' },
  { counterparty: 'АО «Горизонт»', amount: 375_500, status: 'pending' },
  { counterparty: 'ООО «Меридиан»', amount: 112_750, status: 'completed' },
  { counterparty: 'ООО «Вектор»', amount: 89_900, status: 'cancelled' },
  { counterparty: 'АО «Маяк»', amount: 516_200, status: 'completed' },
  { counterparty: 'ООО «Речной порт»', amount: 207_400, status: 'pending' },
];

const currency = new Intl.NumberFormat('ru-RU', {
  style: 'currency',
  currency: 'RUB',
  maximumFractionDigits: 0,
});

const deals: Deal[] = [];
for (let day = 10; day >= 1; day -= 1) {
  for (const deal of MOCK_DEALS) {
    const sequence = deals.length + 1;
    deals.push({
      ...deal,
      id: `СД-${String(sequence).padStart(4, '0')}`,
      date: `${String(day).padStart(2, '0')}.11.2026`,
      amount: deal.amount + sequence * 1_250,
    });
  }
}

const totalAmount = deals.reduce((sum, deal) => sum + deal.amount, 0);

