import * as React from 'react';
import { Button, DrawerDF } from '@daisforge/ui';
import { TableCanvas } from '@daisforge/ui/components/TableCanvas';
import type { ColumnConfig } from '@daisforge/ui/components/TableCanvas';
import { GlobalStyle } from '@daisforge/ui/styles';

type Payment = {
  date: string;
  amount: number;
  status: 'Оплачен' | 'Запланирован';
};

const contractNumber = '2026-0148';

const payments: Payment[] = [
  { date: '05.10.2026', amount: 24500, status: 'Оплачен' },
  { date: '05.11.2026', amount: 24500, status: 'Оплачен' },
  { date: '05.12.2026', amount: 24500, status: 'Запланирован' },
  { date: '05.01.2027', amount: 18750.5, status: 'Запланирован' },
];

const columns: readonly ColumnConfig<Payment>[] = [
  { key: 'date', name: 'Дата платежа', width: 120 },
  {
    key: 'amount',
    name: 'Сумма, ₽',
    width: 105,
    contentFormat: {
      type: 'number',
      locales: ['ru-RU'],
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
      alignContent: 'right',
    },
  },
  { key: 'status', name: 'Статус', width: 135 },
];

const tableConfig = {
  headerRowHeight: 36,
  rowHeight: 40,
  containerStyle: { width: '100%', height: `${36 + payments.length * 40 + 16}px` },
};

function downloadPayments() {
  const csvRows = [
    'Дата платежа;Сумма, ₽;Статус',
    ...payments.map(({ date, amount, status }) =>
      [date, amount.toFixed(2).replace('.', ','), status].join(';'),
    ),
  ];
  const file = new Blob(['\uFEFF', csvRows.join('\r\n'), '\r\n'], {
    type: 'text/csv;charset=utf-8',
  });
  const url = URL.createObjectURL(file);
  const link = document.createElement('a');
  link.href = url;
  link.download = `payments-${contractNumber}.csv`;
  document.body.appendChild(link);

  try {
    link.click();
  } finally {
    link.remove();
    window.setTimeout(() => URL.revokeObjectURL(url), 1000);
  }
}

