        header={<DrawerDF.Header title={`Договор № ${contractNumber}`} />}
        main={
          <DrawerDF.Content fixedWidth="min(460px, 100vw)">
            <section aria-labelledby={paymentsHeadingId}>
              <h2 id={paymentsHeadingId}>График платежей</h2>
              <TableCanvas rows={payments} columnConfig={columns} tableConfig={tableConfig} />
            </section>
          </DrawerDF.Content>
        }
        footer={
