            </Button>
          </DrawerDF.Footer>
        }
      />
    </>
  );
}

import * as React from 'react';
import { Button, DrawerDF, PopupProvider } from '@daisforge/ui';
import { TableCanvas } from '@daisforge/ui/components/TableCanvas';
import type { ColumnConfig } from '@daisforge/ui/components/TableCanvas';
import { GlobalStyle } from '@daisforge/ui/styles';

type Payment = {
  date: string;
  amount: number;
  status: 'Оплачен' | 'Ожидается';
};

const contractNumber = '2026-0417';
const payments: Payment[] = [
  { date: '05.10.2026', amount: 25000, status: 'Оплачен' },
  { date: '05.11.2026', amount: 25000, status: 'Оплачен' },
  { date: '05.12.2026', amount: 25000, status: 'Ожидается' },
  { date: '05.01.2027', amount: 25000, status: 'Ожидается' },
];

const columns: readonly ColumnConfig<Payment>[] = [
  { key: 'date', name: 'Дата платежа', minWidth: 120 },
  { key: 'amount', name: 'Сумма, ₽', minWidth: 100, contentFormat: 'number' },
  { key: 'status', name: 'Статус', minWidth: 105 },
];

function downloadPayments() {
  const csv = [
    'Номер договора;Дата платежа;Сумма, ₽;Статус',
    ...payments.map(({ date, amount, status }) =>
      [contractNumber, date, amount, status].join(';'),
    ),
  ].join('\r\n');

  const file = new Blob(['\uFEFF', csv], { type: 'text/csv;charset=utf-8' });
  const url = URL.createObjectURL(file);
  const link = document.createElement('a');
  link.href = url;
  link.download = `Платежи-${contractNumber}.csv`;
  link.hidden = true;
  document.body.appendChild(link);

  try {
    link.click();
  } finally {
    link.remove();
    window.setTimeout(() => URL.revokeObjectURL(url), 1000);
  }
}

export function ContractDetails() {
  const [opened, setOpened] = React.useState(false);

  function closeDrawer() {
    setOpened(false);
  }

  return (
    <PopupProvider>
      <GlobalStyle />
      <Button
        type="button"
        size="s"
        view="accent"
        aria-haspopup="dialog"
        aria-expanded={opened}
        onClick={() => setOpened(true)}
      >
        Открыть детали договора
      </Button>
      <DrawerDF
        opened={opened}
        placement="right"
        asModal
        closeOnEsc
        closeOnOverlayClick
        onClose={closeDrawer}
        header={<DrawerDF.Header title={`Договор № ${contractNumber}`} />}
        main={
          <DrawerDF.Content>
            <section
              aria-label="График платежей"
              style={{ width: 'min(34rem, calc(100vw - 4rem))' }}
            >
              <TableCanvas
                rows={payments}
                columnConfig={columns}
                tableConfig={{
                  containerStyle: { width: '100%', height: 212 },
                  controlBlock: { show: false },
                  headerRowHeight: 40,
                  rowHeight: 40,
                }}
              />
            </section>
          </DrawerDF.Content>
        }
        footer={
          <DrawerDF.Footer
            $css={{ display: 'flex', justifyContent: 'flex-end', gap: 8 }}
          >
            <Button type="button" size="s" view="secondary" onClick={closeDrawer}>
              Закрыть
            </Button>
            <Button type="button" size="s" view="accent" onClick={downloadPayments}>
              Скачать
            </Button>
          </DrawerDF.Footer>
        }
      />
    </PopupProvider>
  );
}

import * as React from 'react';
import { Button, PageTitle, Steps, TextArea, TextField } from '@daisforge/ui';
import { GlobalStyle } from '@daisforge/ui/styles';

const steps = [
  { indicator: 1, title: 'Данные заявки' },
  { indicator: 2, title: 'Контакты' },
  { indicator: 3, title: 'Проверка' },
];

const lastStep = steps.length - 1;

export function CreateRequestPage() {
  const [activeStep, setActiveStep] = React.useState(0);
  const [subject, setSubject] = React.useState('');
  const [description, setDescription] = React.useState('');
  const [email, setEmail] = React.useState('');
  const stepHeadingId = React.useId();

  return (
    <>
      <GlobalStyle />
      <main
        style={{
          boxSizing: 'border-box',
          maxWidth: 760,
          margin: '0 auto',
          padding: '32px 20px',
          display: 'grid',
          gap: 28,
        }}
      >
        <header>
          <PageTitle title="Создание заявки" />
        </header>

        <Steps items={steps} current={activeStep} size="s" />

        <section aria-labelledby={stepHeadingId} style={{ minHeight: 220 }}>
          <h2 id={stepHeadingId} aria-live="polite" style={{ margin: '0 0 16px' }}>
            {steps[activeStep]?.title}
          </h2>

          {activeStep === 0 && (
            <div style={{ display: 'grid', gap: 16 }}>
              <TextField
                name="subject"
                label="Тема заявки"
                value={subject}
                onChange={(event) => setSubject(event.currentTarget.value)}
              />
              <TextArea
                name="description"
                titleCaption="Описание заявки"
                aria-label="Описание заявки"
                rows={4}
                value={description}
                onChange={(event) => setDescription(event.currentTarget.value)}
              />
            </div>
          )}

          {activeStep === 1 && (
            <TextField
              name="email"
              label="Электронная почта для ответа"
              type="email"
              autoComplete="email"
              value={email}
              onChange={(event) => setEmail(event.currentTarget.value)}
            />
          )}

          {activeStep === 2 && (
            <dl style={{ display: 'grid', gap: 16, margin: 0, overflowWrap: 'anywhere' }}>
              <div>
                <dt>Тема заявки</dt>
                <dd style={{ margin: '4px 0 0' }}>{subject.trim() || 'Не указана'}</dd>
              </div>
              <div>
                <dt>Описание заявки</dt>
                <dd style={{ margin: '4px 0 0', whiteSpace: 'pre-wrap' }}>
                  {description.trim() || 'Не указано'}
                </dd>
              </div>
              <div>
                <dt>Электронная почта для ответа</dt>
                <dd style={{ margin: '4px 0 0' }}>{email.trim() || 'Не указана'}</dd>
              </div>
            </dl>
          )}
        </section>

        <footer style={{ display: 'flex', justifyContent: 'space-between', gap: 12 }}>
          <Button
            type="button"
            size="s"
            view="secondary"
            disabled={activeStep === 0}
            onClick={() => setActiveStep((step) => Math.max(0, step - 1))}
          >
            Назад
          </Button>
          <Button
            type="button"
            size="s"
            view="accent"
            disabled={activeStep === lastStep}
            onClick={() => setActiveStep((step) => Math.min(lastStep, step + 1))}
          >
            Далее
          </Button>
        </footer>
      </main>
    </>
  );
}

